/* 文法の日本語解説と例文。大綱 PDF にはなく、本サイトのために作成したものです。
 * 先生の確認後に使ってください。1行1項目：
 *   id    data/grammar.js の id（r＋級＋番号。変えないでください）
 *   text  対応する語法内容（確認用。data/grammar.js の text と同じ文字列）
 *   ja    やさしい日本語の解説
 *   ex    例文 [[中国語, 日本語訳], ...]（1〜3個） */
window.HSK_GRAMMAR_NOTES = [
{"id":"r1-001","text":"小—、第—","ja":"「小＋名字」は親しみをこめた呼び方（小王＝王くん・王さん）、「第＋数」は順番（第一＝1番目）を表します。","ex":[["小王是我的朋友。","王さんは私の友達です。"],["这是第一课。","これは第1課です。"]]},
{"id":"r1-002","text":"—们、—边","ja":"「～们」は人を表す語について複数を表します（我们・老师们）。「～边」は方向・位置を表す語について場所を表します（这边・外边）。","ex":[["同学们，你们好！","みなさん、こんにちは。"],["外边很冷。","外は寒いです。"]]},
{"id":"r1-003","text":"上、下、里、外、前、后","ja":"位置を表す語（方位詞）です。名詞の後ろにつけて「～の上」「～の中」のように使います。","ex":[["手机在桌子上。","携帯電話は机の上にあります。"],["学校前有一家饭店。","学校の前にレストランが1軒あります。"]]},
{"id":"r1-004","text":"会、能","ja":"動詞の前に置く助動詞です。「会」は練習して身につけた技能（～できる）、「能」は能力や条件があって可能なこと（～できる）を表します。","ex":[["我会说汉语。","私は中国語が話せます。"],["明天我能来。","明日は来られます。"]]},
{"id":"r1-005","text":"想、要","ja":"「想」は「～したい」という願望、「要」は「～するつもりだ・～しなければならない」という、より強い意志を表します。","ex":[["我想喝茶。","お茶が飲みたいです。"],["明天我要去学校。","明日は学校に行きます（行かなければなりません）。"]]},
{"id":"r1-006","text":"可以","ja":"「可以」は「～してもよい」という許可や、「～できる」という可能を表します。","ex":[["我可以坐这儿吗？","ここに座ってもいいですか。"]]},
{"id":"r1-007","text":"看病、睡觉、说话、上课、下课、上班、下班、生病","ja":"「睡觉」「说话」などは「動詞＋目的語」でできた語（離合詞）です。後ろにさらに目的語は置けず、間に「了」などが入ることがあります。","ex":[["他在说话。","彼は話しています。"],["我们下午三点下课。","私たちは午後3時に授業が終わります。"]]},
{"id":"r1-008","text":"多、多少、几、哪、哪儿、哪里、哪些、什么、谁、怎么、怎么样","ja":"疑問詞です。疑問詞を使う疑問文には「吗」をつけません。「几」は10くらいまでの数、「多少」は大きな数や見当のつかない数をたずねます。","ex":[["你叫什么名字？","お名前は何ですか。"],["这个多少钱？","これはいくらですか。"]]},
{"id":"r1-009","text":"我、你、您、他、她、我们、你们、他们、她们、它、它们、大家","ja":"人を指す語です。「您」は「你」の丁寧な形。「他」は男性、「她」は女性、「它」は人以外を指し、複数は「～们」です。「大家」は「みなさん」。","ex":[["您好！","こんにちは。（丁寧）"],["大家好！","みなさん、こんにちは。"]]},
{"id":"r1-010","text":"这、那、这儿、那儿、这里、那里、这些、那些、有的、这个、那个、有些","ja":"「这」は近いもの（これ）、「那」は離れたもの（それ・あれ）を指します。「这儿・这里」は場所、「这些」は複数、「有的・有些」は「一部の」を表します。","ex":[["这是我的书，那是他的书。","これは私の本で、あれは彼の本です。"],["有的人喜欢喝茶。","お茶が好きな人もいます。"]]},
{"id":"r1-011","text":"一、二/两、三、四、五、六、七、八、九、零、十、百、半、千","ja":"数の言い方です。量詞の前では「二」ではなく「两」を使います（两个人）。「半」は「半分」です。","ex":[["我有两个哥哥。","私には兄が2人います。"],["现在三点半。","今3時半です。"]]},
{"id":"r1-012","text":"（1）专用名量词：本、个、家、口、块、件、只、元","ja":"名詞を数えるときは「数＋量詞＋名詞」の形にします。名詞ごとに決まった量詞を使います（本＝本、口＝家族の人数、块＝お金・かたまり、件＝服・事柄、只＝動物など）。","ex":[["我有一只狗。","私は犬を1匹飼っています。"],["这件衣服一百块。","この服は100元です。"]]},
{"id":"r1-013","text":"（2）借用名量词：杯","ja":"容器を表す名詞を、そのまま量詞として使います（一杯茶＝お茶1杯）。","ex":[["我想喝一杯茶。","お茶を1杯飲みたいです。"]]},
{"id":"r1-014","text":"日、号、岁、点、分、年、天","ja":"日付・年齢・時刻・期間を表す語です。「号」は話し言葉の日付、「日」は書き言葉の日付、「岁」は年齢、「点・分」は時刻、「天・年」は日数・年数を表します。","ex":[["今天是五月一号。","今日は5月1日です。"],["我今年二十岁。","私は今年20歳です。"]]},
{"id":"r1-015","text":"非常、很、太、真、有（一）点儿","ja":"形容詞の前に置いて程度を表します。「很」は軽い「とても」、「非常」は強い「非常に」、「太……了」は「～すぎる・とても」、「真」は感嘆、「有点儿」は不満をこめて「少し～」。","ex":[["今天太热了！","今日は暑すぎます。"],["这个有点儿贵。","これはちょっと高いです。"]]},
{"id":"r1-016","text":"都¹","ja":"「都」は「みんな・全部」の意味です。主語の後ろ、動詞の前に置き、前に出た人や物の全部を指します。","ex":[["我们都是学生。","私たちはみんな学生です。"]]},
{"id":"r1-017","text":"在、正在","ja":"動詞の前に置いて、動作が進行中であること（～している）を表します。文末に「呢」をつけることもあります。","ex":[["他在看书。","彼は本を読んでいます。"],["妈妈正在做饭。","母はちょうど料理をしているところです。"]]},
{"id":"r1-018","text":"再¹","ja":"「再」は「もう一度・また」。これから先に動作を繰り返すことを表します。","ex":[["明天再来吧。","また明日来てください。"],["我想再喝一杯。","もう1杯飲みたいです。"]]},
{"id":"r1-019","text":"还¹、也","ja":"「也」は「～も」、「还」は「さらに・その上」を表します。どちらも主語の後ろ、動詞の前に置きます。","ex":[["我也是日本人。","私も日本人です。"],["我有一个哥哥，还有一个妹妹。","私には兄が1人いて、さらに妹も1人います。"]]},
{"id":"r1-020","text":"不、没（有）、不要","ja":"「不」は意志・習慣・形容詞の否定、「没（有）」は過去の事実や「有」の否定、「不要」は「～しないで」という禁止を表します。","ex":[["我不喝咖啡。","私はコーヒーを飲みません。"],["他昨天没来。","彼は昨日来ませんでした。"],["不要说话！","しゃべらないで！"]]},
{"id":"r1-021","text":"在","ja":"「在＋場所＋動詞」で、動作をする場所を表します。","ex":[["我在学校吃饭。","私は学校でご飯を食べます。"]]},
{"id":"r1-022","text":"和¹、对","ja":"「和＋人」は「～と（一緒に）」、「对＋人」は「～に対して」と、動作の相手を表します。","ex":[["我和朋友去商店。","私は友達と店に行きます。"],["老师对我们很好。","先生は私たちにとても親切です。"]]},
{"id":"r1-023","text":"和²","ja":"「A和B」で名詞などを並べて「AとB」を表します。文と文をつなぐことはできません。","ex":[["我和妈妈都喜欢猫。","私と母はどちらも猫が好きです。"]]},
{"id":"r1-024","text":"的¹","ja":"「A的B」で「AのB」を表します。所有や修飾の関係に使います。親しい人間関係（我妈妈）では省略することがあります。","ex":[["这是我的书。","これは私の本です。"],["我喜欢漂亮的衣服。","私はきれいな服が好きです。"]]},
{"id":"r1-025","text":"了¹","ja":"動詞の後ろについて、動作が完了したことを表します。否定は「没（有）＋動詞」で、このとき「了」はつけません。","ex":[["我买了一本书。","私は本を1冊買いました。"],["我没买书。","私は本を買いませんでした。"]]},
{"id":"r1-026","text":"吧¹、了²、吗、呢¹、呢²、呢³","ja":"文末につけて気持ちを表します。「吗」は「～か」、「吧」は推量・提案（～でしょう・～しましょう）、「了」は変化（～になった）、「呢」は聞き返し（～は？）や進行（～しているところ）などを表します。","ex":[["你是学生吗？","あなたは学生ですか。"],["我们走吧。","行きましょう。"],["你呢？","あなたは？"]]},
{"id":"r1-027","text":"喂","ja":"電話に出るときや、人に呼びかけるときの「もしもし・ねえ」です。","ex":[["喂，你好！","もしもし、こんにちは。"]]},
{"id":"r1-028","text":"（1）联合短语","ja":"対等な語を並べたフレーズです（AとB）。","ex":[["爸爸和妈妈都在家。","父と母は2人とも家にいます。"]]},
{"id":"r1-029","text":"（2）偏正短语","ja":"前の語が後ろの語を修飾するフレーズです（修飾語＋中心語）。","ex":[["我的手机","私の携帯電話"],["很好看","とてもきれいだ"]]},
{"id":"r1-030","text":"（3）动宾短语","ja":"「動詞＋目的語」のフレーズです。中国語では目的語を動詞の後ろに置きます。","ex":[["吃饭","ご飯を食べる"],["我喜欢看电影。","私は映画を見るのが好きです。"]]},
{"id":"r1-031","text":"（4）主谓短语","ja":"「主語＋述語」でできたフレーズです。文の一部として、目的語などになることもあります。","ex":[["天气好","天気がいい"],["我知道他是老师。","彼が先生だということを知っています。"]]},
{"id":"r1-032","text":"（1）数量短语","ja":"「数詞＋量詞」でできたフレーズです。名詞の前に置いて数量を表します。","ex":[["我买了三个苹果。","りんごを3個買いました。"]]},
{"id":"r1-033","text":"（2）介宾短语","ja":"「介詞＋名詞」のフレーズです。動詞の前に置いて、場所や相手などを表します。","ex":[["我在家看书。","私は家で本を読みます。"]]},
{"id":"r1-034","text":"（3）方位短语","ja":"「名詞＋方位詞」のフレーズで、場所を表します（桌子上＝机の上）。","ex":[["书在桌子上。","本は机の上にあります。"]]},
{"id":"r1-035","text":"名词、代词或名词性短语作主语","ja":"主語には名詞・代詞・名詞のフレーズなどがなり、述語の前に置きます。","ex":[["我是学生。","私は学生です。"],["我的朋友很漂亮。","私の友達はとてもきれいです。"]]},
{"id":"r1-036","text":"名词、代词、数词或数量短语作谓语","ja":"日付・年齢・値段などは、「是」を使わずに名詞や数量をそのまま述語にできます。否定するときは「不是」を使います。","ex":[["今天星期一。","今日は月曜日です。"],["我二十岁。","私は20歳です。"]]},
{"id":"r1-037","text":"动词或动词性短语、形容词或形容词性短语作谓语","ja":"動詞や形容詞が述語になります。形容詞が述語のときは「是」を使わず、ふつう「很」などをつけます。","ex":[["我喝茶。","私はお茶を飲みます。"],["天气很好。","天気がいいです。"]]},
{"id":"r1-038","text":"名词、代词或名词性短语作宾语","ja":"目的語には名詞・代詞などがなり、動詞の後ろに置きます。","ex":[["我认识他。","私は彼を知っています。"],["我喜欢中国菜。","私は中華料理が好きです。"]]},
{"id":"r1-039","text":"名词性词语、形容词性短语、数量短语作定语","ja":"名詞を修飾する語（連体修飾語）です。名詞の前に置き、多くの場合「的」をつけます。数量を表す語は「的」なしで修飾します。","ex":[["这是妈妈的手机。","これは母の携帯電話です。"],["我有三个中国朋友。","私には中国人の友達が3人います。"]]},
{"id":"r1-040","text":"副词、形容词作状语\n表示时间、处所的词语作状语","ja":"動詞や形容詞を修飾する語（連用修飾語）です。副詞や、時間・場所を表す語は動詞の前に置きます。","ex":[["我明天在家看书。","私は明日家で本を読みます。"],["他很高兴。","彼はとてもうれしそうです。"]]},
{"id":"r1-041","text":"动词+动量补语","ja":"動詞の後ろに「回数（一次・一下など）」を置いて、動作の回数を表します。","ex":[["我去过一次。","私は1回行ったことがあります。"],["请等一下。","少々お待ちください。"]]},
{"id":"r1-042","text":"主谓句1：动词谓语句","ja":"動詞が述語の中心になる文です。語順は「主語＋動詞＋目的語」です。","ex":[["我学习汉语。","私は中国語を勉強しています。"]]},
{"id":"r1-043","text":"主谓句2：形容词谓语句","ja":"形容詞が述語になる文です。「是」は使わず、ふつう「很」などの副詞をつけます。","ex":[["这个苹果很大。","このりんごは大きいです。"]]},
{"id":"r1-044","text":"主谓句3：名词谓语句","ja":"名詞や数量が直接述語になる文です。日付・時刻・年齢・値段などを言うときに使います。","ex":[["现在八点。","今8時です。"],["这个苹果五块。","このりんごは5元です。"]]},
{"id":"r1-045","text":"非主谓句","ja":"主語がない文です。天気・あいさつ・呼びかけなどに使います。","ex":[["下雨了。","雨が降ってきました。"],["谢谢！","ありがとう。"]]},
{"id":"r1-046","text":"","ja":"事実や考えを述べる、ふつうの文（平叙文）です。","ex":[["我是日本人。","私は日本人です。"]]},
{"id":"r1-047","text":"（1）是非问句","ja":"「はい・いいえ」で答える疑問文です。文末に「吗」をつけます。","ex":[["你是老师吗？","あなたは先生ですか。"]]},
{"id":"r1-048","text":"（2）特指问句","ja":"「什么・谁・哪儿」などの疑問詞を使ってたずねる疑問文です。「吗」はつけません。","ex":[["这是什么？","これは何ですか。"],["你去哪儿？","どこへ行くのですか。"]]},
{"id":"r1-049","text":"（3）正反问句","ja":"「肯定＋否定」を並べてたずねる疑問文です（去不去＝行くか行かないか）。「吗」はつけません。","ex":[["你去不去？","行きますか。"],["你有没有手机？","携帯電話を持っていますか。"]]},
{"id":"r1-050","text":"","ja":"命令・依頼・禁止などを表す文です。「请」をつけると丁寧になり、「不要」で禁止を表します。","ex":[["请坐。","どうぞお座りください。"],["不要说话。","しゃべらないでください。"]]},
{"id":"r1-051","text":"","ja":"驚きや感動を表す文です。「太……了」「真……」などを使います。","ex":[["太好了！","よかった！"],["这儿真漂亮！","ここは本当にきれいですね。"]]},
{"id":"r1-052","text":"表示等同或类属","ja":"「A是B」で「AはBである」と、同じものであることや、どの種類に属するかを表します。否定は「不是」です。","ex":[["他是我哥哥。","彼は私の兄です。"],["我不是老师。","私は先生ではありません。"]]},
{"id":"r1-053","text":"表示领有","ja":"「A有B」で「AはBを持っている」と所有を表します。否定は「没有」です。","ex":[["我有一个妹妹。","私には妹が1人います。"],["他没有手机。","彼は携帯電話を持っていません。"]]},
{"id":"r1-054","text":"（1）所处+是+名词","ja":"「場所＋是＋名詞」で「～にあるのは…だ」と、その場所に何があるかを表します。","ex":[["学校前边是一家饭店。","学校の前はレストランです。"]]},
{"id":"r1-055","text":"（2）处所+有+数量短语+名词","ja":"「場所＋有＋数量＋名詞」で「～に…がある・いる」を表します。","ex":[["桌子上有一本书。","机の上に本が1冊あります。"]]},
{"id":"r1-056","text":"（1）前后动作先后发生，后一动作是前一动作的目的","ja":"動詞が二つ続く文（連動文）で、後の動作が前の動作の目的を表します（～しに行く）。","ex":[["我去商店买东西。","私は店へ買い物に行きます。"]]},
{"id":"r1-057","text":"（2）前一动作是后一动作的方式","ja":"連動文で、前の動作が後の動作の手段・方法を表します（～で…する）。","ex":[["我坐飞机去中国。","私は飛行機で中国へ行きます。"]]},
{"id":"r1-058","text":"主语+动词+宾语1+宾语2","ja":"「主語＋動詞＋人＋もの」の形で、目的語を二つとる文です。「给（あげる）」「问（たずねる）」などの動詞で使います。","ex":[["妈妈给了我一个苹果。","母は私にりんごを1つくれました。"],["我问老师一个问题。","私は先生に質問を一つします。"]]},
{"id":"r1-059","text":"","ja":"接続の語を使わず、二つの文を並べてつなぐ複文です。前後の意味から、理由や順序などの関係がわかります。","ex":[["我病了，今天不去学校。","病気になったので、今日は学校に行きません。"]]},
{"id":"r1-060","text":"……，也……","ja":"「……，也……」で「～だし、…も」と、同じようなことを並べます。","ex":[["我喜欢喝茶，也喜欢喝咖啡。","私はお茶が好きで、コーヒーも好きです。"]]},
{"id":"r1-061","text":"……，还……","ja":"「……，还……」で「～、それに…も」と、付け加えることを表します。","ex":[["我买了苹果，还买了面包。","りんごを買って、それにパンも買いました。"]]},
{"id":"r1-062","text":"用动态助词“了¹”表示","ja":"動詞の後ろに「了」をつけると、動作が完了したこと（～した）を表します。","ex":[["我喝了一杯茶。","私はお茶を1杯飲みました。"]]},
{"id":"r1-063","text":"用动态助词“了²”表示","ja":"文末の「了」は、状況が変わったこと（～になった）や、新しい状態になったことを表します。","ex":[["天冷了。","寒くなりました。"],["我二十岁了。","私は20歳になりました。"]]},
{"id":"r1-064","text":"（1）……在/正在+动词","ja":"「在／正在＋動詞」で、動作が進行中であること（～している）を表します。","ex":[["他在睡觉。","彼は寝ています。"]]},
{"id":"r1-065","text":"（2）……在/正在+动词……+呢","ja":"「在／正在＋動詞……呢」のように文末に「呢」を加えると、進行中であることをよりはっきり表します。","ex":[["我们正在上课呢。","私たちは今授業中です。"]]},
{"id":"r1-066","text":"（3）……呢","ja":"話し言葉では、文末の「呢」だけで「今～している」ことを表せます。","ex":[["他看电视呢。","彼はテレビを見ているところです。"]]},
{"id":"r1-067","text":"钱数表示法","ja":"お金は、書き言葉では「元・角・分」、話し言葉では「块・毛・分」で言います。","ex":[["这个多少钱？——十块。","これはいくらですか。――10元です。"],["这本书二十五块。","この本は25元です。"]]},
{"id":"r1-068","text":"序数表达法1：第+数词","ja":"「第＋数」で「～番目」を表します。","ex":[["我是第一次来中国。","私は初めて中国に来ました。"]]},
{"id":"r1-069","text":"（1）年、月、日、星期表示法","ja":"年は数字を一つずつ読み（二〇二六年）、日付は「～月～号（日）」、曜日は「星期＋数字」で表します（星期一＝月曜日、星期天＝日曜日）。","ex":[["今天是二〇二六年五月一号，星期五。","今日は2026年5月1日、金曜日です。"]]},
{"id":"r1-070","text":"（2）钟点表示法","ja":"時刻は「～点～分」で表します。「半」は30分です。","ex":[["现在三点十分。","今3時10分です。"],["我七点半起床。","私は7時半に起きます。"]]},
{"id":"r2-001","text":"面","ja":"「～面」は方向・位置を表す語について、場所を表します（前面・后面・外面）。","ex":[["我家后面有一个超市。","私の家の裏にスーパーがあります。"]]},
{"id":"r2-002","text":"左、右","ja":"「左（ひだり）」「右（みぎ）」です。「左边・右边」の形でもよく使います。","ex":[["往右走。","右へ行ってください。"],["我的左边是小王。","私の左は王さんです。"]]},
{"id":"r2-003","text":"AA、A一A、A了A、ABAB","ja":"動詞を重ねると「ちょっと～する・～してみる」という軽い気持ちを表します。1音節は「看看・看一看」、済んだことは「看了看」、2音節は「休息休息」の形になります。","ex":[["你看看这本书。","この本をちょっと見てみて。"],["我们休息休息吧。","ちょっと休みましょう。"]]},
{"id":"r2-004","text":"可能","ja":"「可能」は「～かもしれない」という推量を表します。","ex":[["明天可能下雨。","明日は雨が降るかもしれません。"]]},
{"id":"r2-005","text":"帮忙、游泳、跳舞、跑步","ja":"「動詞＋目的語」の形の語（離合詞）です。「帮忙」は後ろに人を置けないので、「帮我一个忙」のように間に入れます。","ex":[["你能帮我一个忙吗？","ちょっと手伝ってもらえますか。"],["我每天早上跑步。","私は毎朝ジョギングをします。"]]},
{"id":"r2-006","text":"为什么","ja":"「为什么」は理由をたずねる「なぜ・どうして」です。","ex":[["你为什么不去？","どうして行かないのですか。"]]},
{"id":"r2-007","text":"自己","ja":"「自己」は「自分（で）」です。「我自己（私自身）」のように代詞の後ろにもつけます。","ex":[["这是我自己做的。","これは私が自分で作ったものです。"]]},
{"id":"r2-008","text":"那么、那样、这么、这样、每","ja":"「这么／那么＋形容詞」は「こんなに／あんなに」、「这样／那样」は「このように／あのように」、「每」は「毎～・どの～も」を表します。","ex":[["今天这么冷！","今日はこんなに寒い！"],["我每天都喝牛奶。","私は毎日牛乳を飲みます。"]]},
{"id":"r2-009","text":"AA、AABB","ja":"形容詞を重ねると、程度を強めたり様子を生き生きと表したりします（大大的・高高兴兴）。重ねた形には「很」をつけません。","ex":[["她高高兴兴地回家了。","彼女はうきうきと家に帰りました。"],["他的眼睛大大的。","彼の目はぱっちりと大きい。"]]},
{"id":"r2-010","text":"万、好多、多","ja":"「万」は1万、「好多」は「とてもたくさん」、「数＋多」は「～あまり」（三千多＝3000あまり）を表します。","ex":[["这个手机三千多块。","この携帯電話は3000元あまりです。"],["商店里有好多人。","店にはたくさんの人がいます。"]]},
{"id":"r2-011","text":"（1）专用名量词：条、位、间、名","ja":"「条」は細長いもの（道・川・魚）、「位」は人を丁寧に数えるとき、「间」は部屋、「名」は学生・医者など身分のある人を数えます。","ex":[["这条路很长。","この道はとても長い。"],["我们班有三十名学生。","私たちのクラスには学生が30名います。"]]},
{"id":"r2-012","text":"（2）借用名量词：包","ja":"「包」は袋や包みに入ったものを数えます（一包茶＝お茶1袋）。","ex":[["我买了两包茶。","私はお茶を2袋買いました。"]]},
{"id":"r2-013","text":"次","ja":"「次」は動作の回数（～回）を表し、動詞の後ろに置きます。","ex":[["我去过两次中国。","私は中国に2回行ったことがあります。"]]},
{"id":"r2-014","text":"多、好、最","ja":"「最」は「最も・いちばん」、「好＋形容詞」は「とても～」（話し言葉）、「多＋形容詞」は「なんと～だろう」という感嘆を表します。","ex":[["我最喜欢夏天。","私は夏がいちばん好きです。"],["今天好冷啊！","今日はとても寒いね！"]]},
{"id":"r2-015","text":"一起","ja":"「一起」は「一緒に」です。「和／跟……一起」の形でよく使います。","ex":[["我们一起去吧。","一緒に行きましょう。"]]},
{"id":"r2-016","text":"还²、已经、有时（候）、快、快要、正","ja":"「还」は「まだ」、「已经」は「もう・すでに」、「有时候」は「ときどき」、「快／快要……了」は「もうすぐ」、「正」は「ちょうど（～している）」を表します。","ex":[["他还没来。","彼はまだ来ていません。"],["我已经吃饭了。","私はもうご飯を食べました。"]]},
{"id":"r2-017","text":"常、经常","ja":"「常・经常」は「よく・しょっちゅう」と、動作がたびたび行われることを表します。","ex":[["我经常去图书馆。","私はよく図書館に行きます。"]]},
{"id":"r2-018","text":"别","ja":"「别＋動詞」は「～しないで」という禁止です。「不要」と同じ意味で、話し言葉でよく使います。","ex":[["别走！","行かないで！"]]},
{"id":"r2-019","text":"再²、就¹","ja":"「再」は「それから・その後で」（先……再……）、「就」は「すぐに・それなら」と、前のことを受けて続く動作を表します。","ex":[["吃了饭再走吧。","ご飯を食べてから行きなさい。"],["你等一下，我就来。","ちょっと待って、すぐ行きます。"]]},
{"id":"r2-020","text":"都²、就²、还是¹","ja":"「都……了」は「もう～なのに」、「就」は「まさに・ほかでもなく」という強調、「还是」は「やはり・～したほうがいい」を表します。","ex":[["都十二点了，快睡吧。","もう12時だよ、早く寝なさい。"],["我家就在这儿。","私の家はまさにここです。"],["我们还是坐出租车吧。","やっぱりタクシーに乗りましょう。"]]},
{"id":"r2-021","text":"从¹","ja":"「从＋時間・場所」で「～から」と起点を表します。「从……到……」は「～から…まで」。","ex":[["我从九点到十二点上课。","私は9時から12時まで授業があります。"]]},
{"id":"r2-022","text":"往","ja":"「往＋方向」で「～へ・～に向かって」と、動作の向かう方向を表します。","ex":[["往前走。","前へ進んでください。"]]},
{"id":"r2-023","text":"从²","ja":"「从＋場所」で「～から・～を通って」と、出発点や通り道を表します。","ex":[["他从日本来。","彼は日本から来ました。"],["我们从这儿走吧。","ここを通って行きましょう。"]]},
{"id":"r2-024","text":"给","ja":"「给＋人＋動詞」で「（人）に～する・～してあげる」と、動作を受ける相手を表します。","ex":[["我给妈妈打电话。","私は母に電話をかけます。"]]},
{"id":"r2-025","text":"比","ja":"「A比B＋形容詞」で「AはBより～」と比較を表します。","ex":[["今天比昨天热。","今日は昨日より暑い。"]]},
{"id":"r2-026","text":"跟¹","ja":"「跟＋人」で「～と（一緒に）・～に」と、動作の相手を表します（「和」とほぼ同じ）。","ex":[["我跟朋友一起去。","私は友達と一緒に行きます。"],["我想跟你说一件事。","あなたに話したいことがあります。"]]},
{"id":"r2-027","text":"因为¹","ja":"「因为＋名詞」で「～のために・～が原因で」と原因を表します。","ex":[["因为这件事，他很不高兴。","この件のせいで、彼はとても不機嫌です。"]]},
{"id":"r2-028","text":"跟²","ja":"「A跟B」で「AとB」と名詞を並べます（「和」と同じ）。","ex":[["我跟他都是学生。","私と彼はどちらも学生です。"]]},
{"id":"r2-029","text":"但、但是、那、虽然、还是²、因为²、所以","ja":"文と文をつなぐ語です。「但是・但」は「しかし」、「虽然」は「～だけれども」、「因为……所以……」は理由と結果、「那」は「それなら」、「还是」は疑問文で「それとも」を表します。","ex":[["虽然很贵，但是很好吃。","高いけれど、おいしいです。"],["你不去，那我也不去了。","あなたが行かないなら、私も行くのをやめます。"]]},
{"id":"r2-030","text":"得、地","ja":"「動詞＋得＋様子」は動作の様子（～するのが…だ）、「形容詞など＋地＋動詞」は動作のしかた（～に…する）を表します。","ex":[["他跑得很快。","彼は走るのが速い。"],["她慢慢地走了。","彼女はゆっくり歩いて行った。"]]},
{"id":"r2-031","text":"过","ja":"「動詞＋过」で「～したことがある」という経験を表します。否定は「没（有）＋動詞＋过」です。","ex":[["我去过中国。","私は中国に行ったことがあります。"],["我没吃过饺子。","私はギョーザを食べたことがありません。"]]},
{"id":"r2-032","text":"着","ja":"「動詞＋着」で、状態や動作が続いていること（～している・～してある）を表します。","ex":[["门开着。","ドアが開いています。"],["他笑着说：“好！”","彼は笑いながら「いいよ」と言った。"]]},
{"id":"r2-033","text":"呢⁴、吧²、的²、啊¹","ja":"文末につけて気持ちを表します。「呢」は強調（まだ～よ）、「吧」は確認（～でしょう）、「的」は確信、「啊」は感嘆や語気をやわらげる働きをします。","ex":[["你是日本人吧？","あなたは日本人でしょう？"],["这儿的菜真好吃啊！","ここの料理は本当においしいね！"],["时间还早呢。","時間はまだ早いですよ。"]]},
{"id":"r2-034","text":"动补短语1","ja":"「動詞＋補語」のフレーズです。動作の結果や方向を表します。","ex":[["走进来","歩いて入って来る"],["洗干净","きれいに洗う"]]},
{"id":"r2-035","text":"（1）“的”字短语","ja":"「～的」の形で、後ろの名詞を省いて「～のもの・～の人」を表します（我的＝私のもの）。","ex":[["这本书是我的。","この本は私のです。"],["大的是我的，小的是你的。","大きいのは私ので、小さいのはあなたのです。"]]},
{"id":"r2-036","text":"（2）连谓短语","ja":"動詞（句）が二つ以上続くフレーズです。前後の動作が目的や手段の関係になります。","ex":[["去商店买东西","店に買い物に行く"]]},
{"id":"r2-037","text":"（3）兼语短语","ja":"前の動詞の目的語が、後ろの動詞の主語を兼ねるフレーズです（请他来＝彼に来てもらう）。","ex":[["请他来","彼に来てもらう"],["妈妈让我去买菜。","母は私に野菜を買いに行かせた。"]]},
{"id":"r2-038","text":"","ja":"全体で名詞の働きをするフレーズです。主語や目的語になります。","ex":[["我的新手机很好用。","私の新しい携帯電話はとても使いやすい。"]]},
{"id":"r2-039","text":"","ja":"全体で動詞の働きをするフレーズです。主に述語になります。","ex":[["他喜欢看电影。","彼は映画を見るのが好きです。"]]},
{"id":"r2-040","text":"","ja":"全体で形容詞の働きをするフレーズです（很漂亮・非常高兴）。","ex":[["她今天非常高兴。","彼女は今日とてもうれしそうです。"]]},
{"id":"r2-041","text":"什么的","ja":"いくつかのものを並べた後につけて「～など」を表します（話し言葉）。","ex":[["我买了苹果、香蕉什么的。","りんごやバナナなどを買いました。"]]},
{"id":"r2-042","text":"还是……吧","ja":"「还是……吧」は、比べたうえで「やはり～したほうがいい」と提案します。","ex":[["外面下雨了，我们还是坐出租车吧。","外は雨が降ってきたから、やっぱりタクシーに乗りましょう。"]]},
{"id":"r2-043","text":"要/快要/就要……了","ja":"「（快／就）要……了」で「もうすぐ～する」と、近い未来を表します。具体的な時間の語と一緒に使えるのは「就要」です（明天就要……了）。","ex":[["火车快要开了。","列車はもうすぐ発車します。"],["我明天就要回国了。","私は明日帰国します。"]]},
{"id":"r2-044","text":"都……了","ja":"「都……了」で「もう～なのに」と、時間が遅いことや程度が進んでいることを強調します。","ex":[["都八点了，你怎么还不起床？","もう8時なのに、どうしてまだ起きないの？"]]},
{"id":"r2-045","text":"受事主语","ja":"動作を受けるもの（意味の上では目的語）が主語の位置に来る文です。「被」を使わなくても受け身の意味になります。","ex":[["作业写完了。","宿題は書き終わりました。"],["饭做好了。","ご飯ができました。"]]},
{"id":"r2-046","text":"名词性短语作谓语","ja":"名詞のフレーズが直接述語になる文です。曜日・年齢・出身などを言うときに使います。","ex":[["明天星期六。","明日は土曜日です。"],["他上海人。","彼は上海の人です。"]]},
{"id":"r2-047","text":"动词或动词性短语、主谓短语作定语","ja":"動詞や「主語＋動詞」のフレーズが名詞を修飾します。後ろに「的」をつけます。","ex":[["这是我买的书。","これは私が買った本です。"],["吃的东西在桌子上。","食べ物は机の上にあります。"]]},
{"id":"r2-048","text":"动词+错/懂/好/会/完","ja":"「動詞＋結果補語」で動作の結果を表します。「错」は間違える、「懂」はわかる、「好」はきちんと仕上がる、「会」は身につく、「完」は終わる。","ex":[["我听懂了。","聞いてわかりました。"],["作业写完了吗？","宿題は書き終わりましたか。"]]},
{"id":"r2-049","text":"简单趋向补语的趋向意义用法：（1）动词+来/去","ja":"動詞の後ろに「来（こちらへ）」「去（あちらへ）」をつけて、動作の方向を表します。","ex":[["请进来。","どうぞお入りください。"],["他回去了。","彼は帰って行きました。"]]},
{"id":"r2-050","text":"（2）动词+上/下/进/出/过/回","ja":"動詞の後ろに「上・下・进・出・过・回」をつけて、上へ・下へ・中へ・外へ・通り過ぎる・戻るという方向を表します。","ex":[["请坐下。","どうぞお座りください。"],["他走进教室。","彼は教室に入った。"]]},
{"id":"r2-051","text":"复合趋向补语的趋向意义用法：动词+出来/出去/过来/过去/回来/回去/进来/进去/起来/上来/上去/下来/下去","ja":"動詞の後ろに「上・下・进・出・回・过・起」＋「来／去」をつけて、動作の方向を詳しく表します（走进来＝歩いて入って来る）。","ex":[["他从楼上走下来了。","彼は上の階から歩いて降りて来た。"],["你拿出来看看。","取り出して見てみて。"]]},
{"id":"r2-052","text":"动词+得+形容词性短语","ja":"「動詞＋得＋形容詞のフレーズ」で、動作の様子や程度（～するのが…だ）を表します。目的語があるときは動詞を繰り返します。","ex":[["他说汉语说得很好。","彼は中国語を話すのが上手です。"],["你来得真早！","来るのが本当に早いですね。"]]},
{"id":"r2-053","text":"（1）表示动作持续的时间","ja":"動詞の後ろに時間の長さを置いて、動作がどれくらい続くかを表します。","ex":[["我学了两年汉语。","私は中国語を2年勉強しました。"],["请等五分钟。","5分お待ちください。"]]},
{"id":"r2-054","text":"（2）形容词+数量补语","ja":"「形容詞＋数量」で、基準との差の大きさを表します。","ex":[["我的手表快了五分钟。","私の腕時計は5分進んでいます。"]]},
{"id":"r2-055","text":"主谓句4：主谓谓语句","ja":"述語の部分が「主語＋述語」になっている文です（我身体很好＝私は体が丈夫だ）。","ex":[["我身体很好。","私は体の調子がいいです。"],["这个饭店菜很好吃。","このレストランは料理がおいしい。"]]},
{"id":"r2-056","text":"用“还是”连接的选择问句","ja":"「A还是B？」で「AですかBですか」と、どちらかを選ばせる疑問文です。「吗」はつけません。","ex":[["你喝茶还是喝咖啡？","お茶にしますか、コーヒーにしますか。"]]},
{"id":"r2-057","text":"用“别”的祈使句","ja":"「别＋動詞」で「～しないで」と禁止を表す文です。","ex":[["别说话了。","もうしゃべらないで。"]]},
{"id":"r2-058","text":"表示说明或特征","ja":"「是」を使って、主語がどのようなものかを説明したり、特徴を述べたりします。","ex":[["这本书是新的。","この本は新しいものです。"],["今天是晴天。","今日は晴れです。"]]},
{"id":"r2-059","text":"表示达到","ja":"「有＋数量」で「～ほどある・～に達する」を表します。","ex":[["我弟弟有一米八了。","弟は身長が1メートル80になった。"]]},
{"id":"r2-060","text":"处所+动词+着(+数量短语)+名词","ja":"「場所＋動詞＋着＋（数量）＋名詞」で、その場所に人や物がある状態を表します。","ex":[["门口站着一个人。","入り口に一人立っています。"]]},
{"id":"r2-061","text":"（1）A比B+形容词","ja":"「A比B＋形容詞」で「AはBより～」。形容詞の前に「很・非常」はつけません。","ex":[["哥哥比我高。","兄は私より背が高い。"]]},
{"id":"r2-062","text":"（2）A比B+形容词+数量补语/程度补语","ja":"「A比B＋形容詞」の後ろに、差の大きさ（数量）や「多了・一点儿」をつけます。","ex":[["他比我大两岁。","彼は私より2歳年上です。"],["今天比昨天冷多了。","今日は昨日よりずっと寒い。"]]},
{"id":"r2-063","text":"（3）A有/没有B（+这么/那么）+形容词","ja":"「A有B（那么）～」は「AはBくらい～だ」、「A没有B（那么）～」は「AはBほど～ではない」を表します。","ex":[["我没有他那么高。","私は彼ほど背が高くありません。"]]},
{"id":"r2-064","text":"（4）A比B+动词+得+形容词/A+动词+得+比+B+形容词","ja":"動作の様子を比べるときは「A比B＋動詞＋得＋形容詞」か「A＋動詞＋得＋比B＋形容詞」の形にします。","ex":[["他比我跑得快。","彼は私より走るのが速い。"],["他跑得比我快。","彼は私より走るのが速い。"]]},
{"id":"r2-065","text":"强调时间、地点、方式、动作者","ja":"すでに起きたことについて、時間・場所・方法・動作をした人などを強調するときは「是……的」ではさみます。","ex":[["我是昨天来的。","私は昨日来たのです。"],["你是怎么来的？——我是坐飞机来的。","どうやって来たのですか。――飛行機で来ました。"]]},
{"id":"r2-066","text":"表使令：主语+请/叫/让……+宾语1+动词+宾语2","ja":"「主語＋请／叫／让＋人＋動詞」で「（人）に～してもらう・～させる」を表します。","ex":[["老师让我们读课文。","先生は私たちに本文を読ませた。"],["我请他吃饭。","私は彼に食事をごちそうします。"]]},
{"id":"r2-067","text":"主语+动词+给+宾语1+宾语2","ja":"「送给・借给」のように「動詞＋给＋人＋もの」の形で、ものを人に渡すことを表します。","ex":[["我送给她一本书。","私は彼女に本を1冊贈りました。"]]},
{"id":"r2-068","text":"（是）……，还是……","ja":"「（是）A，还是B？」で「Aですか、それともBですか」とたずねます。","ex":[["你是今天去，还是明天去？","今日行きますか、それとも明日行きますか。"]]},
{"id":"r2-069","text":"虽然……，但是……","ja":"「虽然A，但是B」で「Aだけれども、B」と逆接を表します。","ex":[["虽然汉语很难，但是很有意思。","中国語は難しいけれど、とてもおもしろい。"]]},
{"id":"r2-070","text":"因为……，所以……","ja":"「因为A，所以B」で「Aなので、B」と原因と結果を表します。","ex":[["因为我病了，所以没去学校。","病気だったので、学校に行きませんでした。"]]},
{"id":"r2-071","text":"一……就……","ja":"「一A就B」で「Aするとすぐ B」を表します。","ex":[["我一到家就睡觉了。","家に着くとすぐ寝ました。"]]},
{"id":"r2-072","text":"动词+着：（1）表示状态的持续","ja":"「動詞＋着」で、動作の結果の状態が続いていること（～している・～してある）を表します。","ex":[["他穿着一件白色的衣服。","彼は白い服を着ています。"],["门开着。","ドアが開いています。"]]},
{"id":"r2-073","text":"（2）表示动作的持续","ja":"「動詞＋着」で、動作そのものが続いていることを表します。「動詞1＋着＋動詞2」は「～しながら…する・～して…する」の意味になります。","ex":[["外边下着雨。","外は雨が降っています。"],["我们走着去吧。","歩いて行きましょう。"]]},
{"id":"r2-074","text":"用动态助词“过”表示","ja":"動詞の後ろに「过」をつけて、「～したことがある」という経験を表します。","ex":[["我学过汉语。","私は中国語を学んだことがあります。"]]},
{"id":"r2-075","text":"序数表示法2：数词+量词","ja":"「数＋量詞」だけで順番を表すことがあります（三楼＝3階、二班＝2組）。","ex":[["我住在三楼。","私は3階に住んでいます。"],["我是二班的学生。","私は2組の学生です。"]]},
{"id":"r2-076","text":"概数表达法1：（1）用“几”表示概数","ja":"「几」は疑問だけでなく、「いくつか・数～」というおおよその数も表します（几个人＝数人、十几个＝十数個）。","ex":[["我买了几本书。","私は本を何冊か買いました。"]]},
{"id":"r2-077","text":"（2）数词+多+量词","ja":"「十・百・千」などの後ろに「多」を置いて「～あまり」を表します（二十多个＝20数個）。","ex":[["我们班有二十多个学生。","私たちのクラスには学生が20数人います。"]]},
{"id":"r2-078","text":"（3）数词+量词+多","ja":"一けたの数のときは、量詞の後ろに「多」を置いて「～と少し・～あまり」を表します（一年多＝1年あまり）。","ex":[["我学了一年多汉语。","私は中国語を1年あまり勉強しました。"]]},
{"id":"r3-001","text":"老—","ja":"「老＋姓」は年上や同年代の人への親しい呼び方（老王＝王さん）、「老＋数」は兄弟の順番（老二＝2番目の子）を表します。","ex":[["老王是我的同事。","王さんは私の同僚です。"],["我是家里的老二。","私は家で2番目の子です。"]]},
{"id":"r3-002","text":"—家、—子、—员","ja":"「～家」は専門家（作家・画家）、「～子」は名詞を作る（桌子・孩子）、「～员」は職員・係の人（服务员・运动员）を表します。","ex":[["他是一位有名的作家。","彼は有名な作家です。"],["服务员，请给我一杯水。","すみません（店員さん）、水を1杯ください。"]]},
{"id":"r3-003","text":"东、南、西、北、北方、东方、南方、西方、中间","ja":"方角（東・南・西・北）と「中间（真ん中・間）」を表す語です。「北方」などは「北の地方」の意味でも使います。","ex":[["北方的冬天很冷。","北方の冬はとても寒い。"],["我坐在他们中间。","私は彼らの間に座りました。"]]},
{"id":"r3-004","text":"需要、该、应该、愿意、得","ja":"「需要」は「～する必要がある」、「应该・该」は「～すべきだ」、「愿意」は「～したいと思う・進んで～する」、「得（děi）」は「～しなければならない」（話し言葉）を表します。","ex":[["你应该多休息。","もっと休むべきです。"],["我得走了。","もう行かなければなりません。"]]},
{"id":"r3-005","text":"动宾式离合词：放假、见面、结婚、洗澡","ja":"「動詞＋目的語」の構造の語です。間に「了・过」や回数などが入り（见过面）、後ろに目的語はとれないので「跟＋人＋见面」のように言います。","ex":[["我们明天见面吧。","明日会いましょう。"],["我跟他见过一次面。","私は彼に一度会ったことがあります。"]]},
{"id":"r3-006","text":"动补式离合词：离开、完成、分开","ja":"「動詞＋補語」の構造の語です。可能を表すときは「离得开／离不开」のように間に「得・不」が入ります。","ex":[["他明天要离开中国。","彼は明日中国を離れます。"],["我离不开我的手机。","私は携帯電話を手放せません。"]]},
{"id":"r3-007","text":"怎样","ja":"「怎样」は「どのように・どんな」と方法や様子をたずねます（「怎么样」に近く、やや書き言葉的）。","ex":[["这个字怎样写？","この字はどう書きますか。"]]},
{"id":"r3-008","text":"疑问代词的非疑问用法：\n（1）任指用法：①疑问代词+都……\n②疑问代词+疑问代词","ja":"疑問詞を「何でも・誰でも」の意味で使う用法です。①「疑問詞＋都……」は「どんな～も」、②同じ疑問詞を前後で使うと「～するものを…する」を表します。","ex":[["我什么都想吃。","私は何でも食べたい。"],["你想去哪儿就去哪儿。","行きたいところへ行っていいよ。"]]},
{"id":"r3-009","text":"（2）不定指用法","ja":"疑問詞を「何か・どこか・誰か」の意味で使う用法です。この場合、疑問文にはなりません。","ex":[["我想吃点儿什么。","何か少し食べたい。"],["我好像在哪儿见过他。","どこかで彼に会ったことがあるような気がします。"]]},
{"id":"r3-010","text":"别人、咱们","ja":"「别人」は「ほかの人・他人」、「咱们」は話し相手を含む「私たち」です。","ex":[["别人都走了。","ほかの人はみんな帰りました。"],["咱们一起去吧。","（私たち）一緒に行こうよ。"]]},
{"id":"r3-011","text":"别的、其他","ja":"「别的」「其他」は「ほかの～」を表します。","ex":[["你还要别的吗？","ほかに何か要りますか。"],["其他同学都来了。","ほかの同級生はみんな来ました。"]]},
{"id":"r3-012","text":"（1）专用名量词：把、双、张、种、层、封、页、辆、节、所、班、段、头、句\n公斤、斤、角、毛、刻、米","ja":"名詞ごとに決まった量詞を使います。把＝取っ手のあるもの・いす、双＝対になるもの、张＝平らなもの（紙・机・切符）、辆＝車、封＝手紙、句＝言葉、种＝種類など。公斤・斤・米は重さや長さの単位です。","ex":[["我买了一张票。","切符を1枚買いました。"],["这辆车是谁的？","この車は誰のですか。"]]},
{"id":"r3-013","text":"（2）借用名量词：碗、盘","ja":"「碗（おわん）」「盘（皿）」を、中身を数える量詞として使います。","ex":[["我吃了两碗米饭。","ご飯を2杯食べました。"]]},
{"id":"r3-014","text":"口、回、遍、声","ja":"動作の回数を表す量詞です。「遍」は始めから終わりまで通して1回、「回」は「次」と同じく1回、「口」はひと口、「声」は声を出す回数を表します。","ex":[["请再读一遍。","もう一度読んでください。"],["我喝了一口茶。","お茶をひと口飲みました。"]]},
{"id":"r3-015","text":"个个、张张","ja":"量詞を重ねると「どれもみな・一つ一つ」の意味になります。","ex":[["他们个个都很高。","彼らはみんな背が高い。"],["这些照片张张都很好看。","これらの写真はどれもよく撮れています。"]]},
{"id":"r3-016","text":"比较、还³、更、特别、挺、有些、越、极","ja":"形容詞の前に置いて程度を表します。「比较」は「わりと」、「更・还」は比べて「もっと」、「特别」は「特に」、「挺……的」は「なかなか」、「有些」は「少し」、「极」は「きわめて」です。","ex":[["今天比较冷。","今日はわりと寒い。"],["这个菜挺好吃的。","この料理はなかなかおいしい。"]]},
{"id":"r3-017","text":"就³、一块儿、一共、只、到处、只是","ja":"範囲を表す副詞です。「就・只」は「ただ～だけ」、「一共」は「全部で」、「一块儿」は「一緒に」、「到处」は「至るところ」、「只是」は「ただ～にすぎない」を表します。","ex":[["一共多少钱？","全部でいくらですか。"],["我只有十块钱。","私は10元しか持っていません。"]]},
{"id":"r3-018","text":"才¹、马上、先、一会儿、刚、刚刚、一直","ja":"「才」は「やっと・ようやく（遅い）」、「马上」は「すぐ」、「先」は「先に」、「一会儿」は「しばらく」、「刚・刚刚」は「～したばかり」、「一直」は「ずっと」を表します。","ex":[["他十点才起床。","彼は10時にやっと起きた。"],["我刚到。","私は着いたばかりです。"]]},
{"id":"r3-019","text":"总、总是、又、常常","ja":"「总・总是」は「いつも」、「又」は「また」（すでに起きた繰り返し）、「常常」は「しょっちゅう」を表します。","ex":[["他总是迟到。","彼はいつも遅刻する。"],["他昨天又来了。","彼は昨日また来た。"]]},
{"id":"r3-020","text":"一边","ja":"「一边A一边B」で「AしながらBする」と、二つの動作を同時にすることを表します。","ex":[["他一边听音乐一边写作业。","彼は音楽を聴きながら宿題をしている。"]]},
{"id":"r3-021","text":"大概、必须、差不多、一定、好像、几乎","ja":"話し手の判断を表す副詞です。「大概」は「たぶん」、「必须」は「必ず～しなければならない」、「差不多・几乎」は「ほとんど」、「一定」は「きっと・必ず」、「好像」は「～のようだ」。","ex":[["他大概不来了。","彼はたぶん来ないでしょう。"],["你一定要来！","必ず来てね。"]]},
{"id":"r3-022","text":"当然、其实、终于、才²、才³、就⁴","ja":"話し手の気持ちを表す副詞です。「当然」は「もちろん」、「其实」は「実は」、「终于」は「ついに」、「才」は「～してはじめて・～こそ」、「就」は「まさに・ほかでもなく」を表します。","ex":[["我终于找到了。","ついに見つけた。"],["其实我不喜欢吃鱼。","実は魚が好きではありません。"]]},
{"id":"r3-023","text":"不必、不用","ja":"「不必・不用」は「～する必要はない」を表します。","ex":[["你不用担心。","心配しなくていいよ。"]]},
{"id":"r3-024","text":"为¹、向¹、关于","ja":"「为＋人」は「～のために」、「向＋人」は「～に向かって・～から」、「关于＋事柄」は「～について」を表します。","ex":[["妈妈为我做了一个蛋糕。","母は私のためにケーキを作ってくれた。"],["这是一本关于中国的书。","これは中国についての本です。"]]},
{"id":"r3-025","text":"向²","ja":"「向＋方向」で「～へ・～に向かって」と方向を表します。","ex":[["向前走。","前へ進んでください。"]]},
{"id":"r3-026","text":"为了、为²","ja":"「为了＋目的」「为＋目的」で「～のために」と目的を表します。","ex":[["为了学汉语，他来到了中国。","中国語を学ぶために、彼は中国に来た。"]]},
{"id":"r3-027","text":"把、被","ja":"「把」は目的語を動詞の前に出して「～を（どうする）」を表し、「被」は「～に（…される）」と受け身を表します。","ex":[["我把书放在桌子上了。","私は本を机の上に置いた。"],["我的手机被弟弟拿走了。","携帯電話を弟に持って行かれた。"]]},
{"id":"r3-028","text":"根据","ja":"「根据」は「～に基づいて・～によれば」と根拠を表します。","ex":[["根据大家的意见，我们决定明天出发。","みんなの意見に基づいて、明日出発することにしました。"]]},
{"id":"r3-029","text":"或、或者","ja":"「A或者B」で「AかB（どちらか）」を表します。疑問文では「还是」を使います。","ex":[["你可以喝茶或者咖啡。","お茶かコーヒーを飲めますよ。"]]},
{"id":"r3-030","text":"只有、只要、不但、而且、如果、可¹、可是、然后","ja":"文と文をつなぐ語です。「只有……才」は唯一の条件、「只要……就」は十分な条件、「不但……而且」は累加、「如果」は「もし」、「可是・可」は「しかし」、「然后」は「それから」を表します。","ex":[["如果明天下雨，我就不去了。","もし明日雨なら、行くのをやめます。"],["我们先吃饭，然后去看电影。","まず食事をして、それから映画を見に行きます。"]]},
{"id":"r3-031","text":"的话","ja":"「……的话」で「～なら」と仮定を表します。「如果……的话」の形でもよく使います。","ex":[["你不舒服的话，就回家吧。","具合が悪いなら、家に帰りなさい。"]]},
{"id":"r3-032","text":"同位短语","ja":"同じものを指す二つの語を並べたフレーズです（我们大家＝私たちみんな）。","ex":[["我们大家都很高兴。","私たちはみんなとても喜んでいます。"],["我的朋友小王","私の友達の王さん"]]},
{"id":"r3-033","text":"动补短语2","ja":"「動詞・形容詞＋補語」のフレーズです。結果・方向・可能・程度などを表します。","ex":[["听得懂","聞いてわかる"],["累坏了","ひどく疲れた"]]},
{"id":"r3-034","text":"数量重叠：数词+量词+数词+量词","ja":"「一＋量詞＋一＋量詞」の形で「一つずつ・次々と」を表します。","ex":[["请大家一个一个地进来。","みなさん、一人ずつ入ってください。"]]},
{"id":"r3-035","text":"不A不B","ja":"「不A不B」は、ちょうどよい程度（不大不小＝大きすぎず小さすぎず）や、「～しなければ…しない」（不见不散）を表します。","ex":[["这件衣服不大不小，正合适。","この服は大きすぎず小さすぎず、ちょうどいい。"],["明天八点，不见不散。","明日8時に。会うまで待っていますね。"]]},
{"id":"r3-036","text":"不一会儿","ja":"「不一会儿」は「まもなく・しばらくして」を表します。","ex":[["不一会儿，他就回来了。","まもなく彼は戻って来た。"]]},
{"id":"r3-037","text":"看来","ja":"「看来」は「（状況から見て）どうやら～のようだ」と推測を表します。","ex":[["看来他今天不会来了。","どうやら彼は今日は来ないようだ。"]]},
{"id":"r3-038","text":"在……看来","ja":"「在＋人＋看来」で「～から見れば・～の考えでは」を表します。","ex":[["在我看来，这个办法很好。","私から見れば、この方法はいいと思います。"]]},
{"id":"r3-039","text":"越来越","ja":"「越来越＋形容詞・動詞」で「ますます～」と、程度がだんだん高くなることを表します。","ex":[["天气越来越冷了。","だんだん寒くなってきた。"]]},
{"id":"r3-040","text":"看起来","ja":"「看起来」は「見たところ～のようだ」と、外から見た印象を表します。","ex":[["他看起来很累。","彼は疲れているように見える。"]]},
{"id":"r3-041","text":"看上去","ja":"「看上去」は「見たところ～だ」と、見た目の印象を表します（「看起来」と同じ）。","ex":[["她看上去只有二十岁。","彼女は20歳くらいにしか見えない。"]]},
{"id":"r3-042","text":"一般来说","ja":"「一般来说」は「一般的に言えば・普通は」を表します。","ex":[["一般来说，南方比北方热。","一般に、南の地方は北より暑い。"]]},
{"id":"r3-043","text":"不怎么样","ja":"「不怎么样」は「たいしたことない・あまりよくない」を表します。","ex":[["这家饭店的菜不怎么样。","このレストランの料理はたいしたことない。"]]},
{"id":"r3-044","text":"除了……（以外），……还/也/都……","ja":"「除了A（以外），都……」は「Aを除いてみな～」、「除了A（以外），还／也……」は「Aのほかにさらに～」を表します。","ex":[["除了小王，大家都来了。","王さんのほかは、みんな来ました。"],["除了汉语，我还学英语。","中国語のほかに、英語も勉強しています。"]]},
{"id":"r3-045","text":"从……起","ja":"「从＋時点＋起」で「～から（始めて）」を表します。","ex":[["从明天起，我每天早上跑步。","明日から毎朝ジョギングをします。"]]},
{"id":"r3-046","text":"对……来说","ja":"「对＋人＋来说」で「～にとって」を表します。","ex":[["对我来说，汉字很难。","私にとって、漢字は難しい。"]]},
{"id":"r3-047","text":"一……也/都+不/没……","ja":"「一＋量詞＋名詞＋也／都＋不／没……」で「一つも～ない」と、全くないことを強調します。","ex":[["我一个人也不认识。","私は一人も知り合いがいません。"],["他一口都没吃。","彼はひと口も食べなかった。"]]},
{"id":"r3-048","text":"一点儿也不","ja":"「一点儿也不＋形容詞・動詞」で「少しも～ない」を表します。","ex":[["这个菜一点儿也不辣。","この料理は少しも辛くない。"]]},
{"id":"r3-049","text":"越……越……","ja":"「越A越B」で「AすればするほどBになる」を表します。","ex":[["雨越下越大。","雨はますます激しくなった。"],["我越学越喜欢汉语。","勉強すればするほど中国語が好きになる。"]]},
{"id":"r3-050","text":"（在）……以前/以后/前/后","ja":"「（在）＋時間・出来事＋以前／以后（前／后）」で「～の前に／～の後で」を表します。","ex":[["吃饭以前要洗手。","ご飯を食べる前に手を洗いましょう。"],["下课以后我去图书馆。","授業の後で図書館に行きます。"]]},
{"id":"r3-051","text":"X什么（啊）","ja":"「X什么（啊）」は相手の言葉を受けて「何が～なものか（～なんかじゃない）」と、反対や不満を表します（話し言葉）。","ex":[["贵什么啊，一点儿也不贵。","何が高いもんか、ちっとも高くないよ。"]]},
{"id":"r3-052","text":"该……了","ja":"「该……了」で「もう～する時間だ・～しなければならない」を表します。","ex":[["该睡觉了。","もう寝る時間です。"]]},
{"id":"r3-053","text":"在……上/下/中","ja":"「在……上」は「～の面で」、「在……下」は「～のもとで」、「在……中」は「～の中で・～の間に」と、範囲や条件を表します。","ex":[["在学习上，他帮了我很多。","勉強の面で、彼は私をたくさん助けてくれた。"],["在老师的帮助下，我的汉语水平提高了很多。","先生の助けのもとで、私の中国語のレベルはずいぶん上がった。"]]},
{"id":"r3-054","text":"动词或动词性短语、形容词或形容词性短语作主语","ja":"動詞や形容詞（のフレーズ）が、そのまま主語になることができます。","ex":[["学汉语很有意思。","中国語を学ぶのはとてもおもしろい。"],["认真最重要。","まじめであることが一番大切です。"]]},
{"id":"r3-055","text":"主谓短语作主语","ja":"「主語＋述語」のフレーズが、文全体の主語になります。","ex":[["他不来没关系。","彼が来なくても構いません。"]]},
{"id":"r3-056","text":"多项定语","ja":"一つの名詞に修飾語が複数つくときは、ふつう「だれの → 数量 → どんな」の順に並べます。","ex":[["我的两个好朋友","私の二人の親友"],["这是我昨天买的一本新书。","これは私が昨日買った新しい本です。"]]},
{"id":"r3-057","text":"动词+到/住/走/上","ja":"「到」は目的の達成・到達、「住」はしっかり止まる・固定する、「走」は離れていく、「上」は閉じる・達成するという結果を表す補語です。","ex":[["我找到了我的手机。","携帯電話を見つけました。"],["请记住我的名字。","私の名前をしっかり覚えてください。"]]},
{"id":"r3-058","text":"趋向补语的引申用法：（1）表示结果意义：动词+出/起/下","ja":"方向補語が本来の方向ではなく結果を表す用法です。「出」は現れ出る・見分ける、「起」は思い起こす、「下」は残す・書き留めるなどを表します。","ex":[["我想起了他的名字。","彼の名前を思い出しました。"],["请写下你的电话号码。","電話番号を書き留めてください。"]]},
{"id":"r3-059","text":"（2）表示动作行为的开始：动词+上/起来","ja":"「動詞＋起来」「動詞＋上」で、動作や状態が始まることを表します。","ex":[["大家都笑起来了。","みんな笑い出した。"],["他爱上了这个城市。","彼はこの町が好きになった。"]]},
{"id":"r3-060","text":"（3）表示动作行为的持续：动词+下去/下来","ja":"「動詞＋下去」はこれから先も続けること、「動詞＋下来」は過去から今まで続いてきたことを表します。","ex":[["请说下去。","どうぞ話を続けてください。"],["你要坚持下去。","続けていかなければいけませんよ。"]]},
{"id":"r3-061","text":"动词+得/不+动词/形容词","ja":"動詞と結果・方向補語の間に「得」を入れると「～できる」、「不」を入れると「～できない」を表します。","ex":[["你听得懂吗？——听不懂。","聞いてわかりますか。――わかりません。"],["这么多菜，我吃不完。","こんなにたくさんの料理、食べきれません。"]]},
{"id":"r3-062","text":"（1）形容词+得很","ja":"「形容詞＋得很」で「とても～だ」と程度の高さを表します。","ex":[["今天热得很。","今日はとても暑い。"]]},
{"id":"r3-063","text":"（2）形容词/动词+极了/坏了","ja":"「～极了」は「この上なく～」、「～坏了」は「ひどく～」と、程度がきわめて高いことを表します。","ex":[["这个菜好吃极了！","この料理はすごくおいしい！"],["我饿坏了。","おなかがぺこぺこです。"]]},
{"id":"r3-064","text":"表示动作结束到某个时间点的间隔时间","ja":"「動詞（＋目的語）＋時間＋了」で、ある動作が終わってから今までに経った時間（～して…になる）を表します。","ex":[["我来中国三年了。","中国に来て3年になります。"],["他毕业两年了。","彼は卒業して2年になる。"]]},
{"id":"r3-065","text":"“怎样+动词”的特指问句","ja":"「怎样＋動詞」で「どのように～するか」と方法をたずねます。","ex":[["这个菜怎样做？","この料理はどうやって作りますか。"]]},
{"id":"r3-066","text":"用反问句表示强调：不是……吗？","ja":"「不是……吗？」は「～ではないか」と、相手も知っていることを強く確認する反語文です。","ex":[["你不是去过中国吗？","中国に行ったことがあるんじゃないの？"]]},
{"id":"r3-067","text":"（1）主语+把+宾语+动词+在/到+处所","ja":"「主語＋把＋目的語＋動詞＋在／到＋場所」で、ものをある場所に移すことを表します。","ex":[["我把书放在桌子上了。","私は本を机の上に置いた。"],["请把这封信送到他家。","この手紙を彼の家に届けてください。"]]},
{"id":"r3-068","text":"（2）主语+把+宾语1+动词（+给）+宾语2","ja":"「主語＋把＋もの＋動詞（＋给）＋人」で、ものを人に渡すことを表します。","ex":[["我把书还给他了。","私は本を彼に返しました。"]]},
{"id":"r3-069","text":"（3）主语+把+宾语+动词+结果补语/趋向补语/状态补语","ja":"「把」構文の動詞の後ろには結果・方向などの補語をつけ、目的語をどう処置したかを表します。動詞だけで終わることはできません。","ex":[["我把作业做完了。","宿題をやり終えました。"],["请把门关上。","ドアを閉めてください。"]]},
{"id":"r3-070","text":"（1）主语+被+宾语+动词+其他成分","ja":"「主語＋被＋動作をした人＋動詞＋その他」で受け身を表します。よくないことに使うことが多いです。","ex":[["我的自行车被小王骑走了。","私の自転車は王さんに乗っていかれた。"]]},
{"id":"r3-071","text":"（2）主语+被+动词+其他成分","ja":"動作をした人がわからないときや言う必要がないときは、「被」の後ろに直接動詞を置きます。","ex":[["我的蛋糕被吃了。","私のケーキが食べられてしまった。"]]},
{"id":"r3-072","text":"“着”表示动作的伴随：动词1+着+动词2","ja":"「動詞1＋着＋動詞2」で「～しながら・～した状態で…する」と、後の動作がどんな様子で行われるかを表します。","ex":[["他笑着说：“没关系。”","彼は笑いながら「大丈夫」と言った。"],["我们坐着聊天吧。","座っておしゃべりしましょう。"]]},
{"id":"r3-073","text":"（1）A比B+更/还+形容词","ja":"比較文で「もっと～」と言うときは、形容詞の前に「更」か「还」をつけます。「很・非常」は使えません。","ex":[["今天比昨天更冷。","今日は昨日よりさらに寒い。"]]},
{"id":"r3-074","text":"（2）A跟B一样","ja":"「A跟B一样」で「AはBと同じだ」を表します。否定は「不一样」です。","ex":[["我的手机跟你的一样。","私の携帯電話はあなたのと同じです。"]]},
{"id":"r3-075","text":"（3）A跟B一样+形容词","ja":"「A跟B一样＋形容詞」で「AはBと同じくらい～だ」を表します。","ex":[["我跟哥哥一样高。","私は兄と同じくらいの背の高さです。"]]},
{"id":"r3-076","text":"（4）A不比B+形容词","ja":"「A不比B＋形容詞」は「AはBより～というわけではない（ほぼ同じだ）」を表します。","ex":[["我不比他高。","私は彼より背が高いわけではありません。"]]},
{"id":"r3-077","text":"（5）A比B+多/少/早/晚+动词+数量短语","ja":"「A比B＋早／晚／多／少＋動詞＋数量」で、動作の差を表します。","ex":[["我比他早来了十分钟。","私は彼より10分早く来ました。"],["他比我多吃了一碗饭。","彼は私よりご飯を1杯多く食べた。"]]},
{"id":"r3-078","text":"（1）表示出现：处所词+动词+趋向补语/结果补语+动态助词（了）+数量短语+人/物","ja":"「場所＋動詞＋補語＋了＋数量＋人・もの」で、ある場所に人やものが現れることを表します。","ex":[["前面走过来一个人。","前から一人歩いて来た。"],["我们班来了一个新同学。","私たちのクラスに新しい同級生が来た。"]]},
{"id":"r3-079","text":"（2）表示消失：处所词+动词+结果补语+动态助词（了）+数量短语+人/物","ja":"「場所＋動詞（＋補語）＋了＋数量＋人・もの」で、ある場所から人やものがいなくなる・なくなることを表します。","ex":[["我们班走了两个同学。","私たちのクラスから同級生が2人去っていった。"]]},
{"id":"r3-080","text":"强调说话人的看法或态度","ja":"「是……的」で、話し手の考えや態度（確信・断定）を強調します。","ex":[["这件事是不可能的。","そのことはありえない。"],["你的想法是对的。","あなたの考えは正しい。"]]},
{"id":"r3-081","text":"主语+动词+宾语+动词+补语","ja":"目的語と補語の両方を言うときは動詞を繰り返し、「動詞＋目的語＋同じ動詞＋補語」の形にします。","ex":[["他说汉语说得很好。","彼は中国語を話すのが上手だ。"],["我等你等了一个小时。","私はあなたを1時間待った。"]]},
{"id":"r3-082","text":"先……，再/然后……","ja":"「先A，再／然后B」で「まずAして、それからBする」と順序を表します。","ex":[["我们先吃饭，再去看电影。","まず食事をして、それから映画を見に行きましょう。"]]},
{"id":"r3-083","text":"或者……，或者……","ja":"「或者A，或者B」で「AかBか（どちらか）」を表します（平叙文で使います）。","ex":[["周末我或者在家看书，或者去公园。","週末は家で本を読むか、公園に行くかです。"]]},
{"id":"r3-084","text":"一会儿……，一会儿……","ja":"「一会儿A，一会儿B」で「Aしたかと思うとBする」と、短い間に変わることを表します。","ex":[["天气一会儿冷，一会儿热。","天気は寒くなったり暑くなったりする。"]]},
{"id":"r3-085","text":"又……，又……","ja":"「又A又B」で「AでもありBでもある」と、二つの性質や動作が同時にあることを表します。","ex":[["这家的饺子又便宜又好吃。","この店のギョーザは安くておいしい。"]]},
{"id":"r3-086","text":"一边……，一边……","ja":"「一边A一边B」で「AしながらBする」を表します。","ex":[["我们一边吃饭，一边聊天。","私たちはご飯を食べながらおしゃべりした。"]]},
{"id":"r3-087","text":"不但……，而且……","ja":"「不但A，而且B」で「Aだけでなく、Bも」を表します。","ex":[["她不但会唱歌，而且会跳舞。","彼女は歌が歌えるだけでなく、踊りもできる。"]]},
{"id":"r3-088","text":"虽然……，可是……","ja":"「虽然A，可是B」で「Aだけれども、B」と逆接を表します（「但是」と同じ）。","ex":[["虽然很累，可是我很高兴。","疲れたけれど、とてもうれしい。"]]},
{"id":"r3-089","text":"如果……，就……","ja":"「如果A，就B」で「もしAなら、B」と仮定を表します。","ex":[["如果明天不下雨，我们就去爬山。","もし明日雨が降らなければ、山登りに行きます。"]]},
{"id":"r3-090","text":"……的话，就……","ja":"「A的话，就B」で「Aなら、B」と仮定を表します（話し言葉的）。","ex":[["你有时间的话，就来我家玩儿吧。","時間があったら、うちに遊びに来てね。"]]},
{"id":"r3-091","text":"只有……，才……","ja":"「只有A，才B」で「AしてはじめてB（Aしなければ Bできない）」と、唯一の条件を表します。","ex":[["只有多练习，才能说好汉语。","たくさん練習してこそ、中国語を上手に話せるようになる。"]]},
{"id":"r3-092","text":"只要……，就……","ja":"「只要A，就B」で「AさえすればB」と、十分な条件を表します。","ex":[["只要你努力，就一定能学好。","努力さえすれば、きっと身につきます。"]]},
{"id":"r3-093","text":"为了……，……","ja":"「为了A，B」で「Aするために、Bする」と目的を表します。","ex":[["为了身体健康，我每天跑步。","健康のために、私は毎日ジョギングをしています。"]]},
{"id":"r3-094","text":"……了……（就）……","ja":"「動詞1＋了（＋就）＋動詞2」で「～したら（すぐ）…する」を表します。","ex":[["我下了课就去找你。","授業が終わったらすぐあなたのところへ行きます。"]]},
{"id":"r3-095","text":"概数表达法2：（1）用“大概”表示概数","ja":"「大概＋数量」で「だいたい～」と、おおよその数を表します。","ex":[["从这儿到车站大概要十分钟。","ここから駅までだいたい10分かかります。"]]},
{"id":"r3-096","text":"（2）相邻数词连用表示概数","ja":"隣り合う数を続けて「～か…」とおおよその数を表します（三四个＝3、4個）。","ex":[["教室里有七八个人。","教室には7、8人います。"],["我等了他三四十分钟。","私は彼を30～40分待った。"]]},
{"id":"r4-001","text":"敢","ja":"「敢」は「～する勇気がある・思い切って～する」を表します。否定は「不敢」です。","ex":[["我不敢一个人走夜路。","私は一人で夜道を歩く勇気がありません。"]]},
{"id":"r4-002","text":"各、各位、各种、任何、此","ja":"「各」は「それぞれの」、「各位」は「みなさま」、「各种」は「さまざまな」、「任何」は「どんな～でも」、「此」は「これ・この」（書き言葉）を表します。","ex":[["各位同学，大家好！","学生のみなさん、こんにちは。"],["有任何问题都可以问我。","どんな質問でも聞いてください。"]]},
{"id":"r4-003","text":"（1）专用名量词：打、袋、棵、台、幅","ja":"「打」は1ダース（12個）、「袋」は袋に入ったもの、「棵」は木や草、「台」は機械、「幅」は絵や布を数えます。","ex":[["院子里有两棵树。","庭に木が2本あります。"],["我买了一台电脑。","パソコンを1台買いました。"]]},
{"id":"r4-004","text":"（2）借用名量词：脸、手、盒、屋子、桌子","ja":"「一脸（顔じゅう）」「一屋子（部屋いっぱい）」のように名詞を借りて「～いっぱいの」を表します。「盒」は箱に入ったものを数えます。","ex":[["他出了一脸汗。","彼は顔じゅう汗をかいた。"],["一屋子的人都笑了。","部屋いっぱいの人がみんな笑った。"]]},
{"id":"r4-005","text":"场、顿、趟","ja":"動作の回数を表す量詞です。「场」はひとしきりの出来事（雨・試合・病気）、「顿」は食事や叱責、「趟」は行って帰る1往復を表します。","ex":[["昨天下了一场大雨。","昨日大雨が降った。"],["我回了一趟家。","私は一度家に帰った。"]]},
{"id":"r4-006","text":"十分、更加、稍、稍微、尤其、多么","ja":"「十分」は「非常に」、「更加」は「さらに」、「稍・稍微」は「少し」、「尤其」は「特に」、「多么」は感嘆の「なんと」を表します。","ex":[["这里的风景十分美。","ここの景色は非常に美しい。"],["请稍微等一下。","少々お待ちください。"]]},
{"id":"r4-007","text":"共、全、光、仅、仅仅、至少","ja":"「共」は「全部で」、「全」は「すべて」、「光・仅・仅仅」は「ただ～だけ」、「至少」は「少なくとも」を表します。","ex":[["全班同学都来了。","クラス全員が来た。"],["至少要三天。","少なくとも3日かかります。"]]},
{"id":"r4-008","text":"按时、从来、赶紧、赶快、已、忽然、将、将要、从、本来","ja":"「按时」は「時間どおりに」、「从来・从」は「これまで（否定と一緒に：从来没／从不）」、「赶紧・赶快」は「急いで」、「已」は「すでに」、「忽然」は「突然」、「将・将要」は「まもなく～する」、「本来」は「もともと」を表します。","ex":[["我从来没去过中国。","私はこれまで中国に行ったことがありません。"],["忽然下起雨来了。","突然雨が降り出した。"]]},
{"id":"r4-009","text":"重新、往往、偶尔、再次、老","ja":"「重新」は「改めて・やり直して」、「往往」は「（経験上）よく～しがちだ」、「偶尔」は「たまに」、「再次」は「再び」、「老」は「いつも」（話し言葉）を表します。","ex":[["请你重新写一遍。","もう一度書き直してください。"],["我偶尔也喝咖啡。","私もたまにコーヒーを飲みます。"]]},
{"id":"r4-010","text":"故意、互相、相互","ja":"「故意」は「わざと」、「互相・相互」は「互いに」を表します。","ex":[["他不是故意的。","彼はわざとやったのではありません。"],["我们应该互相帮助。","私たちは助け合うべきです。"]]},
{"id":"r4-011","text":"却","ja":"「却」は「ところが・しかし」と、予想に反することを表します。主語の後ろに置きます。","ex":[["我叫了他很多次，他却没听见。","何度も呼んだのに、彼は聞こえなかった。"]]},
{"id":"r4-012","text":"也许、恐怕","ja":"「也许」は「もしかすると～かもしれない」、「恐怕」は「（よくないことが）おそらく～だろう」を表します。","ex":[["他也许已经走了。","彼はもう行ってしまったかもしれない。"],["恐怕要下雨了。","どうやら雨になりそうだ。"]]},
{"id":"r4-013","text":"才⁴、就⁵、并¹、还⁴、竟然、究竟、正好、到底、难道、千万、确实、只好、差（一）点儿","ja":"話し手の気持ちを表す副詞です。「并＋否定」は「決して～ない」、「竟然」は「意外にも」、「究竟・到底」は「いったい」、「正好」は「ちょうど」、「难道」は「まさか」、「千万」は「くれぐれも」、「确实」は「確かに」、「只好」は「～するしかない」、「差点儿」は「危うく～するところだった」を表します。","ex":[["他竟然忘了我的名字。","彼はなんと私の名前を忘れていた。"],["我差点儿迟到。","危うく遅刻するところでした。"]]},
{"id":"r4-014","text":"自、当、由¹、随着、等¹","ja":"「自」は「～から」（書き言葉）、「当……的时候」は「～のとき」、「由」は「～から」、「随着」は「～につれて」、「等……」は「～してから・～になったら」を表します。","ex":[["随着经济的发展，人们的生活越来越好。","経済の発展につれて、人々の生活はますますよくなった。"],["等我回来再说吧。","私が戻ってから話しましょう。"]]},
{"id":"r4-015","text":"将、由²、叫、让","ja":"「将」は「把」と同じく目的語を前に出す（書き言葉）、「由」は「～によって・～が（担当する）」、「叫・让」は受け身の「～に（…される）」を表します。","ex":[["请将手机关上。","携帯電話の電源を切ってください。"],["这件事由我负责。","この件は私が担当します。"]]},
{"id":"r4-016","text":"由于¹","ja":"「由于＋名詞」で「～によって・～のために」と原因を表します。","ex":[["由于天气的原因，飞机晚点了。","天候のため、飛行機が遅れた。"]]},
{"id":"r4-017","text":"对于、与¹","ja":"「对于」は「～に対して・～について」、「与」は「～と」（書き言葉）を表します。","ex":[["对于这个问题，大家有什么看法？","この問題について、みなさんはどう考えますか。"],["我想与你谈一谈。","あなたと少し話したいです。"]]},
{"id":"r4-018","text":"作为、按、按照","ja":"「作为」は「～として」、「按・按照」は「～に従って・～どおりに」を表します。","ex":[["作为学生，应该好好学习。","学生として、しっかり勉強するべきだ。"],["请按照说明书使用。","説明書に従って使ってください。"]]},
{"id":"r4-019","text":"并²、而¹、与²","ja":"語や語句をつなぐ接続詞です。「并」は動詞をつないで「そして」、「而」は形容詞などをつないで「～で（あり）・～だが」、「与」は名詞をつないで「～と」（書き言葉）を表します。","ex":[["大会讨论并通过了这个计划。","大会はこの計画を討論し、可決した。"],["老师与学生","先生と学生"]]},
{"id":"r4-020","text":"此外、而²、既然、甚至、不过、并且","ja":"文をつなぐ接続詞です。「此外」は「このほか」、「而」は「しかし・一方」、「既然」は「～である以上」、「甚至」は「さらには」、「不过」は「ただし・でも」、「并且」は「そのうえ」を表します。","ex":[["这件衣服很漂亮，不过有点儿贵。","この服はきれいだけど、ちょっと高い。"],["他学过英语、法语，甚至还学过日语。","彼は英語、フランス語、さらには日本語まで学んだことがある。"]]},
{"id":"r4-021","text":"不光、不仅、另外、要是、因此、由于²、加上","ja":"「不光・不仅」は「～だけでなく」、「另外」は「ほかに」、「要是」は「もし」、「因此」は「それゆえ」、「由于」は「～なので」、「加上」は「それに加えて」を表します。","ex":[["由于下大雨，比赛推迟了。","大雨のため、試合は延期された。"],["天气很冷，加上我没穿大衣，所以感冒了。","寒かったうえにコートを着ていなかったので、風邪をひいた。"]]},
{"id":"r4-022","text":"等²、者、之、就是","ja":"「等」は「～など」、「者」は「～する人」（读者＝読者）、「之」は「～の」（書き言葉）、文末の「就是」は「～すればいい・それで済む」を表します。","ex":[["我买了苹果、香蕉等水果。","りんごやバナナなどの果物を買った。"],["我一定去，你放心就是。","必ず行くから、安心して。"]]},
{"id":"r4-023","text":"啊、嗯","ja":"「啊」は驚きや感嘆（ああ・わあ）、「嗯」は相づちや同意（うん）を表します。","ex":[["啊，下雪了！","わあ、雪だ！"],["嗯，我知道了。","うん、わかった。"]]},
{"id":"r4-024","text":"数词+形容词+量词","ja":"「数＋形容詞（大・小など）＋量詞」の形で、数量と大きさを一緒に表します（一大杯＝大きなコップ1杯）。","ex":[["他喝了一大杯水。","彼は大きなコップで水を1杯飲んだ。"],["一小块蛋糕","小さなケーキひとかけら"]]},
{"id":"r4-025","text":"一A一B","ja":"「一A一B」は、対になる語を並べて、そっくり・ひたすら・やりとりなどを表します（一模一样＝そっくり、一问一答＝一問一答）。","ex":[["他们俩长得一模一样。","あの二人はそっくりだ。"],["老师和学生一问一答。","先生と学生が一問一答する。"]]},
{"id":"r4-026","text":"无A无B","ja":"「无A无B」は、AもBもないことを表します（无忧无虑＝何の心配もない）。","ex":[["小时候我们无忧无虑。","子どもの頃、私たちは何の心配もなかった。"]]},
{"id":"r4-027","text":"有A有B","ja":"「有A有B」は、AもBもあること、AとBがそろっていることを表します（有说有笑＝しゃべったり笑ったりする）。","ex":[["大家有说有笑，非常热闹。","みんなしゃべったり笑ったりして、とてもにぎやかだ。"]]},
{"id":"r4-028","text":"来得及/来不及","ja":"「来得及」は「（時間的に）間に合う」、「来不及」は「間に合わない」を表します。","ex":[["现在走还来得及。","今出ればまだ間に合う。"],["来不及了，快走吧！","間に合わないよ、早く行こう！"]]},
{"id":"r4-029","text":"有的是","ja":"「有的是」は「いくらでもある・たくさんある」を表します。","ex":[["时间有的是，别着急。","時間はいくらでもあるから、焦らないで。"]]},
{"id":"r4-030","text":"说不定","ja":"「说不定」は「～かもしれない・どうなるかわからない」を表します。","ex":[["他说不定已经到了。","彼はもう着いているかもしれない。"]]},
{"id":"r4-031","text":"不怎么","ja":"「不怎么＋形容詞・動詞」で「あまり～ない」を表します。","ex":[["我不怎么喜欢吃甜的。","私は甘いものがあまり好きではありません。"]]},
{"id":"r4-032","text":"就是说/这就是说","ja":"「就是说・这就是说」は「つまり・言い換えれば」と、前の内容を説明し直します。","ex":[["他明天走，就是说我们只有今天了。","彼は明日発つ。つまり私たちには今日しかないということだ。"]]},
{"id":"r4-033","text":"一+量词+比+一+量词","ja":"「一＋量詞＋比＋一＋量詞」で「～ごとにますます」と、だんだん変化することを表します。","ex":[["天气一天比一天冷。","日に日に寒くなる。"]]},
{"id":"r4-034","text":"在……方面","ja":"「在……方面」で「～の面で」を表します。","ex":[["在学习方面，他很努力。","勉強の面では、彼はとても努力している。"]]},
{"id":"r4-035","text":"够……的","ja":"「够＋形容詞＋的」で「十分に～だ・かなり～だ」と、程度が高いことを表します（話し言葉）。","ex":[["今天够冷的。","今日はかなり寒い。"]]},
{"id":"r4-036","text":"拿……来说","ja":"「拿……来说」は「～を例にとると」を表します。","ex":[["拿我来说，我每天学习两个小时。","私を例にとると、毎日2時間勉強しています。"]]},
{"id":"r4-037","text":"再也不/没……","ja":"「再也不／没……」で「二度と～しない・それきり～しなかった」を表します。","ex":[["我再也不迟到了。","もう二度と遅刻しません。"],["他走了以后，再也没回来。","彼は行ったきり、二度と戻らなかった。"]]},
{"id":"r4-038","text":"怎么都/也+不/没……","ja":"「怎么都／也＋不／没……」で「どうしても～ない」を表します。","ex":[["这道题我怎么也做不出来。","この問題はどうしても解けない。"]]},
{"id":"r4-039","text":"为了……而……","ja":"「为了A而B」で「Aのために Bする」と目的を表します（書き言葉的）。","ex":[["他为了理想而努力。","彼は理想のために努力している。"]]},
{"id":"r4-040","text":"动词+一X是一X","ja":"「動詞＋一X是一X」は「少しでも～できればそれだけよい」、または「その場その場で～する」という気持ちを表します。","ex":[["钱能省一点是一点。","お金は少しでも節約できればそれだけいい。"]]},
{"id":"r4-041","text":"（没）有什么（好）X的","ja":"「有什么（好）X的」「没（有）什么（好）X的」で「～するほどのことはない」と、否定や不満を表します。","ex":[["这有什么好哭的？","こんなことで泣くことないでしょう。"],["没什么好担心的。","心配することなんて何もない。"]]},
{"id":"r4-042","text":"X是X，Y是Y","ja":"「X是X，Y是Y」で「XはX、YはY（別のもの）」と、二つを区別すべきことを表します。","ex":[["工作是工作，休息是休息。","仕事は仕事、休みは休み。"]]},
{"id":"r4-043","text":"X也得X，不X也得X","ja":"「X也得X，不X也得X」で「～したくてもしたくなくても、どうしても～しなければならない」を表します。","ex":[["这个药你吃也得吃，不吃也得吃。","この薬は、いやでも飲まなければいけません。"]]},
{"id":"r4-044","text":"X就是了","ja":"「X就是了」で「～すればいい（それで済む）」と、相手を安心させたり軽く言い切ったりします。","ex":[["你别着急，我明天还你就是了。","焦らないで。明日返すから。"]]},
{"id":"r4-045","text":"还X呢","ja":"「还X呢」で「それでも～なのか」と、ふさわしくないことを皮肉ったり非難したりします。","ex":[["还大学生呢，这么简单的题都不会。","それでも大学生なの、こんな簡単な問題もできないなんて。"]]},
{"id":"r4-046","text":"你X你的吧","ja":"「你X你的吧」で「（私にかまわず）あなたは自分の～を続けて」を表します。","ex":[["你忙你的吧，我自己走。","あなたは自分の用事を続けて。私は一人で行くから。"]]},
{"id":"r4-047","text":"让/叫你X你就X","ja":"「让／叫你X你就X」で「～しろと言われたら、そのとおりにすればいい」を表します。","ex":[["让你坐你就坐吧，别客气。","座ってと言われたら座ればいいのよ、遠慮しないで。"]]},
{"id":"r4-048","text":"说什么/怎么（着）也得X","ja":"「说什么／怎么（着）也得X」で「何と言っても・どうしても～しなければならない」を表します。","ex":[["今天说什么也得把作业做完。","今日は何としても宿題を終わらせなければ。"]]},
{"id":"r4-049","text":"X就X（点儿）吧","ja":"「X就X（点儿）吧」で「～なら～でかまわない」と、しかたなく受け入れる気持ちを表します。","ex":[["贵就贵点儿吧，质量好就行。","少し高くてもかまわない、品質がよければいい。"]]},
{"id":"r4-050","text":"X是X","ja":"「X是X，（不过／但是）……」で「Xであることは確かにXだが…」と、一応認めたうえで別のことを言います。","ex":[["这件衣服好看是好看，就是太贵了。","この服はきれいはきれいだけど、高すぎる。"]]},
{"id":"r4-051","text":"形容词/心理动词+死了/厉害","ja":"「～死了」「～得厉害」で「ひどく～・死ぬほど～」と、程度がきわめて高いことを表します（話し言葉）。","ex":[["今天热死了。","今日は死ぬほど暑い。"],["我的头疼得厉害。","頭がひどく痛い。"]]},
{"id":"r4-052","text":"动词+得/不+了","ja":"「動詞＋得了（liǎo）」は「～できる・～しきれる」、「動詞＋不了」は「～できない・～しきれない」を表します。","ex":[["这么多菜，我吃不了。","こんなにたくさんの料理、食べきれません。"],["明天你来得了吗？","明日来られますか。"]]},
{"id":"r4-053","text":"难道……吗？","ja":"「难道……吗？」は「まさか～ではないだろう」と、強い疑問や驚き・非難を表す反語文です。","ex":[["难道你不知道吗？","まさか知らないわけじゃないでしょう。"]]},
{"id":"r4-054","text":"由疑问代词构成的反问句","ja":"「谁・什么・哪儿・怎么」などの疑問詞を使って、反対の意味を強く言う反語文です（谁不知道？＝誰でも知っている）。","ex":[["谁不想去中国？","中国に行きたくない人なんていない。"],["我哪儿有时间？","私に時間なんてあるもんか。"]]},
{"id":"r4-055","text":"（1）主语+把+宾语+动词（+一/了）+动词","ja":"「把」構文で動詞を重ねて「ちょっと～する」を表します。","ex":[["你把房间打扫打扫吧。","部屋をちょっと掃除しなさい。"],["我把这本书看了看。","この本にざっと目を通した。"]]},
{"id":"r4-056","text":"（2）主语+把+宾语+动词+了","ja":"「主語＋把＋目的語＋動詞＋了」で、目的語を処置した結果（～してしまった）を表します。","ex":[["我把那个苹果吃了。","あのりんごは私が食べてしまった。"]]},
{"id":"r4-057","text":"（3）主语+把+宾语+动词+动量补语/时量补语","ja":"「把」構文の動詞の後ろに、回数や時間の長さを置きます。","ex":[["我把这篇课文读了三遍。","私はこの本文を3回読んだ。"]]},
{"id":"r4-058","text":"（4）主语+把+宾语+状语+动词","ja":"「把＋目的語」の後ろ、動詞の前に、動作のしかたを表す語を置きます。","ex":[["别把东西到处乱放。","物をあちこちに散らかしてはいけない。"]]},
{"id":"r4-059","text":"主语+叫/让+宾语+动词+其他成分","ja":"話し言葉では「被」の代わりに「叫・让」も使います。このときは動作をした人を必ず言います。","ex":[["我的蛋糕让弟弟吃了。","私のケーキは弟に食べられてしまった。"]]},
{"id":"r4-060","text":"（1）表爱憎义：主语+表扬/批评+宾语1+动词+宾语2","ja":"「表扬（ほめる）・批评（しかる）＋人＋動詞句」で、ある行いについて人をほめたり、しかったりすることを表します。","ex":[["老师表扬他学习努力。","先生は彼が熱心に勉強していることをほめた。"]]},
{"id":"r4-061","text":"（2）表称谓或认定义：主语+收/选+宾语1+做/当/为+宾语2","ja":"「收／选＋人＋做／当／为＋名詞」で、人を何かとして受け入れる・選ぶことを表します。","ex":[["大家选他当班长。","みんなは彼をクラス委員長に選んだ。"]]},
{"id":"r4-062","text":"（3）表致使：主语+使/让+人称代词+动词短语","ja":"「使／让＋人＋動詞句」で「（人）を～させる・～の気持ちにさせる」を表します。","ex":[["这件事让我很感动。","このことに私はとても感動した。"],["他的话使我明白了很多。","彼の言葉で私は多くのことがわかった。"]]},
{"id":"r4-063","text":"（1）A不如B（+形容词）","ja":"「A不如B（＋形容詞）」で「AはBに及ばない」を表します。","ex":[["我的汉语不如他好。","私の中国語は彼ほど上手ではない。"],["坐车不如走路快。","車に乗るより歩いたほうが速い。"]]},
{"id":"r4-064","text":"（2）跟……相比","ja":"「跟……相比」で「～と比べると」を表します。","ex":[["跟去年相比，今年的冬天暖和多了。","去年と比べると、今年の冬はずっと暖かい。"]]},
{"id":"r4-065","text":"用双重否定表示强调","ja":"否定を二つ重ねて、強い肯定を表します（不得不＝～せざるを得ない、没有……不……＝～しないものはない）。","ex":[["我不得不走了。","行かざるを得なくなった。"],["没有人不喜欢他。","彼を好きでない人はいない。"]]},
{"id":"r4-066","text":"不是……，而是……","ja":"「不是A，而是B」で「AではなくBだ」を表します。","ex":[["他不是不想来，而是太忙了。","彼は来たくないのではなく、忙しすぎるのだ。"]]},
{"id":"r4-067","text":"既……，又/也……","ja":"「既A又／也B」で「AでもありBでもある」を表します。","ex":[["她既聪明又努力。","彼女は頭がいいうえに努力家だ。"]]},
{"id":"r4-068","text":"一方面……，另一方面……","ja":"「一方面A，另一方面B」で「一方ではA、もう一方ではB」と、二つの面を並べます。","ex":[["我来中国，一方面是学汉语，另一方面是了解中国文化。","私が中国に来たのは、一つには中国語を学ぶため、もう一つには中国文化を知るためです。"]]},
{"id":"r4-069","text":"首先……，其次……","ja":"「首先A，其次B」で「まずA、次にB」と、順序や重要度を述べます。","ex":[["首先要了解问题，其次要找到办法。","まず問題を理解し、次に方法を見つけなければならない。"]]},
{"id":"r4-070","text":"首先……，然后……","ja":"「首先A，然后B」で「まずAして、それからBする」と、動作の順序を表します。","ex":[["首先打开电脑，然后输入密码。","まずパソコンを起動し、それからパスワードを入力します。"]]},
{"id":"r4-071","text":"……，于是……","ja":"「……，于是……」で「そこで・それで」と、前のことを受けて次のことが起こることを表します。","ex":[["天黑了，于是我们回家了。","暗くなったので、私たちは家に帰った。"]]},
{"id":"r4-072","text":"……,甚至……","ja":"「……，甚至……」で「さらには～まで」と、程度が進んだことを付け加えます。","ex":[["他忙得没时间吃饭，甚至没时间睡觉。","彼は忙しくて食事の時間もなく、寝る時間さえない。"]]},
{"id":"r4-073","text":"不仅/不光……，还/而且……","ja":"「不仅／不光A，还／而且B」で「Aだけでなく、Bも」を表します。","ex":[["他不仅会说汉语，还会说日语。","彼は中国語だけでなく、日本語も話せる。"]]},
{"id":"r4-074","text":"……，并且……","ja":"「……，并且……」で「そのうえ・しかも」と、付け加えることを表します。","ex":[["他完成了作业，并且检查了一遍。","彼は宿題を終え、さらに一度見直した。"]]},
{"id":"r4-075","text":"连……也/都……，……更……","ja":"「连A也／都……，B更……」で「Aでさえ～なのだから、Bはなおさら～だ」を表します。","ex":[["连老师都不知道，我们更不知道了。","先生でさえ知らないのだから、私たちはなおさら知らない。"]]},
{"id":"r4-076","text":"不是……，就是……","ja":"「不是A，就是B」で「AでなければB（そのどちらか）」を表します。","ex":[["周末他不是在家看书，就是去打球。","週末、彼は家で本を読んでいるか、球技をしに行くかのどちらかだ。"]]},
{"id":"r4-077","text":"尽管……，但是/可是……","ja":"「尽管A，但是／可是B」で「Aにもかかわらず、B」を表します。","ex":[["尽管很累，但是他还是坚持工作。","とても疲れているにもかかわらず、彼は仕事を続けた。"]]},
{"id":"r4-078","text":"……，然而……","ja":"「……，然而……」で「しかし・ところが」と逆接を表します（書き言葉的）。","ex":[["大家都以为他会赢，然而他输了。","みんな彼が勝つと思っていたが、彼は負けた。"]]},
{"id":"r4-079","text":"……，不过……","ja":"「……，不过……」で「でも・ただし」と、軽い逆接や補足を表します。","ex":[["这个菜很好吃，不过有点儿辣。","この料理はおいしいけど、ちょっと辛い。"]]},
{"id":"r4-080","text":"……X是X，就是/不过……","ja":"「X是X，就是／不过……」で「Xであることは確かだが、ただ…」と、一応認めたうえで問題点を言います。","ex":[["这个房间大是大，就是有点儿吵。","この部屋は広いことは広いけど、ちょっとうるさい。"]]},
{"id":"r4-081","text":"……，否则……","ja":"「A，否则B」で「Aしなさい。さもないとBになる」を表します。","ex":[["快点儿走吧，否则要迟到了。","早く行こう、さもないと遅刻するよ。"]]},
{"id":"r4-082","text":"要是……，就……","ja":"「要是A，就B」で「もしAなら、B」と仮定を表します（話し言葉的）。","ex":[["要是明天不下雨，我们就去爬山。","もし明日雨が降らなければ、山登りに行きます。"]]},
{"id":"r4-083","text":"要是……，（就）……，否则……","ja":"「要是A，（就）B，否则C」で「もしAならB、そうでなければC」と、二つの場合を述べます。","ex":[["要是你有时间，就来帮帮我，否则我一个人做不完。","時間があったら手伝って。そうでないと一人では終わらないから。"]]},
{"id":"r4-084","text":"不管……，都/也……","ja":"「不管A，都／也B」で「Aにかかわらず B」を表します。Aには疑問詞や「A还是B」などを使います。","ex":[["不管天气怎么样，我都去。","天気がどうであれ、私は行きます。"]]},
{"id":"r4-085","text":"无论……，都/也……","ja":"「无论A，都／也B」で「Aにかかわらず B」を表します（「不管」より書き言葉的）。","ex":[["无论遇到什么困难，我们都不放弃。","どんな困難にあっても、私たちはあきらめない。"]]},
{"id":"r4-086","text":"既然……，就……","ja":"「既然A，就B」で「Aである以上・Aなら、B」を表します。","ex":[["既然你不舒服，就早点儿休息吧。","具合が悪いなら、早めに休みなさい。"]]},
{"id":"r4-087","text":"（由于）……，因此……","ja":"「（由于）A，因此B」で「Aなので、それゆえB」と、原因と結果を表します（書き言葉的）。","ex":[["由于工作很忙，因此他很少回家。","仕事が忙しいので、彼はめったに家に帰らない。"]]},
{"id":"r4-088","text":"……，好……","ja":"「A，好B」で「Bできるように Aする」と目的を表します（話し言葉）。","ex":[["你把电话号码留下，我好跟你联系。","電話番号を残しておいて。連絡できるように。"]]},
{"id":"r4-089","text":"即使……，也……","ja":"「即使A，也B」で「たとえAでも B」と、仮定の譲歩を表します。","ex":[["即使明天下雨，我们也要去。","たとえ明日雨が降っても、私たちは行きます。"]]},
{"id":"r4-090","text":"就是……，也……","ja":"「就是A，也B」で「たとえAでも B」を表します（「即使」と同じで、話し言葉的）。","ex":[["就是再忙，你也要吃饭。","どんなに忙しくても、ご飯は食べなきゃだめよ。"]]},
{"id":"r4-091","text":"无标记","ja":"接続の語を使わず、短い二つの文を一つにまとめた文です。前後の意味から条件・仮定などの関係がわかります。","ex":[["不去不行。","行かないわけにはいかない。"],["有问题问老师。","問題があったら先生に聞きなさい。"]]},
{"id":"r4-092","text":"不……也……","ja":"「不A也B」で「Aしなくても Bだ」を表します。","ex":[["你不说我也知道。","あなたが言わなくても私はわかっている。"]]},
{"id":"r4-093","text":"概数表示法3：数词+来+量词","ja":"「十・百」などの後ろに「来」を置いて「～くらい」を表します（十来个＝10個くらい）。","ex":[["来了二十来个人。","20人くらい来た。"]]},
{"id":"r4-094","text":"用“大约、左右、前后”表示概数","ja":"「大约＋数」「数＋左右」で「約～・～くらい」、「時点＋前后」で「～の前後」を表します。","ex":[["我大约等了半个小时。","私は約30分待った。"],["他三十岁左右。","彼は30歳くらいです。"]]},
{"id":"r4-095","text":"小数、分数、百分数、倍数的表示法","ja":"小数は「点」（3.5＝三点五）、分数は「～分之～」（3分の1＝三分之一）、パーセントは「百分之～」、倍数は「～倍」で表します。","ex":[["三分之一的学生是日本人。","学生の3分の1は日本人です。"],["今年的价格是去年的两倍。","今年の価格は去年の2倍です。"]]},
{"id":"r5-001","text":"—头","ja":"「～头」は名詞を作る接尾辞です（木头＝木、石头＝石）。動詞・形容詞について「～する値打ち」を表すこともあります（看头＝見どころ）。","ex":[["这个电影没什么看头。","この映画は見どころがあまりない。"],["桌子是木头做的。","机は木でできている。"]]},
{"id":"r5-002","text":"彼此、如此、本","ja":"「彼此」は「お互い」、「如此」は「このように・こんなに」（書き言葉）、「本」は「本～・この～」（本人・本校）を表します。","ex":[["我们彼此帮助。","私たちはお互いに助け合う。"],["原来如此！","なるほど、そういうことか。"]]},
{"id":"r5-003","text":"册、朵、届、颗、匹、行、架、群、支、根、批、束、副、集、周","ja":"名詞ごとの量詞です。册＝冊、朵＝花、届＝（大会・卒業の）回、颗＝粒状のもの、匹＝馬、行＝行（ぎょう）、架＝飛行機など、群＝群れ、支・根＝細長いもの、批＝ひとまとまり、束＝束、副＝対のもの（眼鏡）、集＝ドラマの話、周＝週を数えます。","ex":[["她送给我一束花。","彼女は私に花束をくれた。"],["这部电视剧一共有三十集。","このドラマは全部で30話ある。"]]},
{"id":"r5-004","text":"眼","ja":"「眼」は見る回数を数えます（看一眼＝ちらっと見る）。","ex":[["他看了我一眼。","彼は私をちらっと見た。"]]},
{"id":"r5-005","text":"过于、相当、较¹、可²、格外、极其","ja":"「过于」は「～すぎる」、「相当」は「かなり」、「较」は「比較的」、「可」は強調の「とても」、「格外」は「ひときわ」、「极其」は「きわめて」を表します。","ex":[["这个问题相当复杂。","この問題はかなり複雑だ。"],["今天的月亮格外圆。","今日の月はひときわ丸い。"]]},
{"id":"r5-006","text":"时刻、曾经、立刻、连忙、始终、早已、即将、急忙、渐渐、尽快、早晚","ja":"「时刻」は「常に」、「曾经」は「かつて」、「立刻・连忙・急忙」は「すぐに・急いで」、「始终」は「終始」、「早已」は「とっくに」、「即将」は「まもなく」、「渐渐」は「だんだん」、「尽快」は「できるだけ早く」、「早晚」は「遅かれ早かれ」を表します。","ex":[["我曾经在上海住过两年。","私はかつて上海に2年住んでいた。"],["请尽快回复。","できるだけ早く返事をください。"]]},
{"id":"r5-007","text":"老是、通常、时常","ja":"「老是」は「いつも（よくないことに）」、「通常」は「普通は・たいてい」、「时常」は「しょっちゅう」を表します。","ex":[["他老是忘带钥匙。","彼はいつも鍵を持っていくのを忘れる。"],["我通常七点起床。","私はたいてい7時に起きます。"]]},
{"id":"r5-008","text":"尽量、亲自","ja":"「尽量」は「できるだけ」、「亲自」は「自ら・自分で」を表します。","ex":[["我会尽量早点儿到。","できるだけ早く着くようにします。"],["校长亲自来看我们。","校長が自ら私たちを訪ねて来た。"]]},
{"id":"r5-009","text":"便、一旦","ja":"「便」は「就」と同じく「すぐに・それで」（書き言葉的）、「一旦」は「いったん～したら」を表します。","ex":[["他吃完饭便走了。","彼は食事を終えるとすぐ帰った。"],["一旦下雨，比赛就取消。","いったん雨が降れば、試合は中止になる。"]]},
{"id":"r5-010","text":"似乎、仿佛","ja":"「似乎・仿佛」は「～のようだ・まるで～のようだ」と、推測やたとえを表します。","ex":[["他似乎不太高兴。","彼はあまり機嫌がよくないようだ。"],["我仿佛又回到了小时候。","まるで子どもの頃に戻ったようだ。"]]},
{"id":"r5-011","text":"毕竟、居然、反正、根本、果然、简直、绝对、的确、反而、白、刚好、可³","ja":"話し手の気持ちを表す副詞です。「毕竟」は「なんといっても」、「居然」は「意外にも」、「反正」は「どうせ」、「根本＋否定」は「まったく～ない」、「果然」は「やはり」、「简直」は「まるで」、「绝对」は「絶対に」、「的确」は「確かに」、「反而」は「かえって」、「白」は「むだに」、「刚好」は「ちょうど」を表します。","ex":[["我根本不认识他。","私は彼をまったく知らない。"],["我白等了一个小时。","1時間むだに待った。"],["天气预报说今天下雨，果然下了。","天気予報で今日は雨と言っていたが、やはり降った。"]]},
{"id":"r5-012","text":"自从","ja":"「自从＋過去の時点」で「～から（ずっと）」と、ある時から今までを表します。","ex":[["自从来到中国，我每天都说汉语。","中国に来てから、私は毎日中国語を話している。"]]},
{"id":"r5-013","text":"朝、沿（着）","ja":"「朝＋方向」は「～に向かって」、「沿（着）＋場所」は「～に沿って」を表します。","ex":[["他朝我走过来。","彼は私のほうに歩いて来た。"],["我们沿着河边散步。","私たちは川沿いを散歩した。"]]},
{"id":"r5-014","text":"替、同¹、较²","ja":"「替＋人」は「～の代わりに・～のために」、「同＋人」は「～と」（「跟」と同じ）、「较」は「～と比べて」（書き言葉）を表します。","ex":[["请你替我向他问好。","私の代わりに彼によろしく伝えてください。"],["今年的收入较去年有所增加。","今年の収入は去年と比べていくらか増えた。"]]},
{"id":"r5-015","text":"凭","ja":"「凭＋名詞」で「～に頼って・～によって」を表します。","ex":[["他凭自己的努力考上了大学。","彼は自分の努力で大学に合格した。"],["凭票入场。","入場には切符が必要です。"]]},
{"id":"r5-016","text":"据","ja":"「据」は「～によれば・～に基づいて」を表します（据说＝聞くところによれば）。","ex":[["据说明天会下雪。","聞くところによると、明日は雪が降るそうだ。"]]},
{"id":"r5-017","text":"依据","ja":"「依据」は「～に基づいて・～に従って」を表します（書き言葉）。","ex":[["依据法律，他应该受到处罚。","法律に基づき、彼は処罰されるべきだ。"]]},
{"id":"r5-018","text":"以及、同²","ja":"「以及」は「および」と、名詞などを並べます（書き言葉）。「同」は「～と」と名詞をつなぎます。","ex":[["老师、学生以及家长都参加了。","先生、学生および保護者がみな参加した。"],["我同他是老朋友。","私と彼は古い友人だ。"]]},
{"id":"r5-019","text":"从而、可见、假如、总之","ja":"「从而」は「それによって」、「可见」は「このことから～がわかる」、「假如」は「もし」、「总之」は「要するに」を表します。","ex":[["我们改进了方法，从而提高了效率。","方法を改善し、それによって効率を高めた。"],["总之，我不同意。","要するに、私は賛成しない。"]]},
{"id":"r5-020","text":"似的","ja":"「（像）……似的」で「まるで～のようだ」を表します。","ex":[["她高兴得像个孩子似的。","彼女は子どものように喜んだ。"]]},
{"id":"r5-021","text":"A来A去","ja":"「A来A去」は同じ動作を何度も繰り返すことを表します（想来想去＝あれこれ考える）。","ex":[["我想来想去，还是决定不去了。","あれこれ考えたが、やはり行かないことにした。"]]},
{"id":"r5-022","text":"A着A着","ja":"「A着A着」は「～しているうちに」と、ある動作の途中で別のことが起きることを表します。","ex":[["孩子哭着哭着就睡着了。","子どもは泣いているうちに眠ってしまった。"]]},
{"id":"r5-023","text":"没A没B","ja":"「没A没B」は、AもBもないこと（あるべきものがないこと）を表します（没大没小＝目上への礼儀がない）。","ex":[["这孩子说话没大没小的。","この子は目上の人への口のきき方がなっていない。"]]},
{"id":"r5-024","text":"说A就A","ja":"「说A就A」で「Aと言ったらすぐにAする」と、すばやい行動や急な変化を表します。","ex":[["他说走就走了。","彼は行くと言ったらすぐ行ってしまった。"],["这里的天气说变就变。","ここの天気はすぐに変わる。"]]},
{"id":"r5-025","text":"不得了","ja":"「不得了」は「大変だ」、また「～得不得了」の形で「ものすごく～」を表します。","ex":[["不得了了，着火了！","大変だ、火事だ！"],["他高兴得不得了。","彼はものすごく喜んでいる。"]]},
{"id":"r5-026","text":"用不着","ja":"「用不着」は「～する必要はない」を表します。","ex":[["你用不着担心。","心配する必要はないよ。"]]},
{"id":"r5-027","text":"从……来看","ja":"「从……来看」で「～から見ると」と、判断のよりどころや観点を表します。","ex":[["从这次考试来看，他的汉语进步了很多。","今回の試験から見ると、彼の中国語はずいぶん上達した。"]]},
{"id":"r5-028","text":"A的A，B的B","ja":"「A的A，B的B」で「Aする人はAし、Bする人はBする」と、それぞれがいろいろなことをしている様子を表します。","ex":[["下课后，大家唱歌的唱歌，跳舞的跳舞。","授業の後、みんな歌う人は歌い、踊る人は踊った。"]]},
{"id":"r5-029","text":"（自）……以来","ja":"「（自）……以来」で「～以来（ずっと）」を表します。","ex":[["自上大学以来，他一直住在学校。","大学に入ってから、彼はずっと学校に住んでいる。"]]},
{"id":"r5-030","text":"由……组成","ja":"「由……组成」で「～から成る・～で構成される」を表します。","ex":[["这个班由二十个学生组成。","このクラスは20人の学生で構成されている。"]]},
{"id":"r5-031","text":"X也不是，Y也不是","ja":"「X也不是，Y也不是」で「XしてもだめYしてもだめ」と、どうしてよいかわからない困った様子を表します。","ex":[["他站也不是，坐也不是，非常紧张。","彼は立っても座っても落ち着かず、とても緊張していた。"]]},
{"id":"r5-032","text":"X也X不得，Y也Y不得","ja":"「X也X不得，Y也Y不得」で「XすることもYすることもできない」と、板ばさみの状態を表します。","ex":[["这件事让我哭也哭不得，笑也笑不得。","この件には泣くに泣けず、笑うに笑えない。"]]},
{"id":"r5-033","text":"X是它，Y也是它","ja":"「X是它，Y也是它」で「Xさせるのもそれ、Yさせるのもそれ」と、同じものが良い結果にも悪い結果にもなることを表します。","ex":[["成功是它，失败也是它。","成功をもたらすのもそれなら、失敗をもたらすのもそれだ。"]]},
{"id":"r5-034","text":"X着也是X着","ja":"「X着也是X着」で「どうせ～しているだけなら」と、時間や物をむだにしないで何かしようという気持ちを表します。","ex":[["闲着也是闲着，我来帮你吧。","どうせ暇なんだから、手伝うよ。"]]},
{"id":"r5-035","text":"不管怎样说","ja":"「不管怎样说」で「何と言っても・いずれにせよ」を表します。","ex":[["不管怎样说，他是你的哥哥。","何と言っても、彼はあなたの兄なのだから。"]]},
{"id":"r5-036","text":"真有你/他/她的","ja":"「真有你的」で「さすがだね・たいしたものだ」と、感心やあきれた気持ちを表します。","ex":[["这么难的题你都会，真有你的！","こんな難しい問題もできるなんて、さすがだね！"]]},
{"id":"r5-037","text":"X什么X","ja":"「X什么X」で「～なんかするな・～することはない」と、相手の行動を止めたり不満を表したりします。","ex":[["哭什么哭！","泣くんじゃない！"],["急什么急，时间还早呢。","何を焦っているの、まだ時間は早いよ。"]]},
{"id":"r5-038","text":"什么X不X（的）","ja":"「什么X不X（的）」で「～かどうかなんて（問題ではない）」と、気にしない気持ちを表します。","ex":[["什么贵不贵的，喜欢就买吧。","高いかどうかなんて関係ない、気に入ったなら買いなよ。"]]},
{"id":"r5-039","text":"不X白不X","ja":"「不X白不X」で「～しないと損だ（どうせなら～しよう）」を表します。","ex":[["免费的，不吃白不吃。","無料なんだから、食べないと損だ。"]]},
{"id":"r5-040","text":"X来X去，都是/就是……","ja":"「X来X去，都是／就是……」で「あれこれ～しても、結局は…だ」を表します。","ex":[["他说来说去，就是不想去。","彼はあれこれ言っているが、結局行きたくないのだ。"]]},
{"id":"r5-041","text":"动词+什么（就）是什么","ja":"「動詞＋什么（就）是什么」で「～したとおりのものになる・何でもそれに従う」を表します。","ex":[["你说什么就是什么，我都听你的。","あなたの言うとおりにします。全部あなたに従います。"]]},
{"id":"r5-042","text":"多项状语","ja":"動詞の前に連用修飾語がいくつも並ぶときは、ふつう「時間 → 場所 → 様子 → 対象」の順に置きます。","ex":[["我们明天在学校门口见面。","私たちは明日学校の門の前で会います。"],["他昨天在家高兴地给妈妈打了电话。","彼は昨日家でうれしそうに母に電話をかけた。"]]},
{"id":"r5-043","text":"动词+得/不得","ja":"「動詞＋得」は「～してもよい・～できる」、「動詞＋不得」は「～してはいけない・～できない」を表します。","ex":[["这种东西吃不得。","こういうものは食べてはいけない。"],["这件事马虎不得。","この件はいい加減にしてはいけない。"]]},
{"id":"r5-044","text":"形容词/心理动词+得+不得了","ja":"「～得不得了」で「ものすごく～」と、程度がきわめて高いことを表します。","ex":[["听到这个消息，他高兴得不得了。","その知らせを聞いて、彼はものすごく喜んだ。"]]},
{"id":"r5-045","text":"趋向补语的引申用法：表示状态意义：动词/形容词+下来/下去/起来/过来/过去","ja":"方向補語が状態の変化を表す用法です。「下来」は静まる・暗くなる、「下去」は状態が続く、「起来」は状態が始まる・高まる、「过来」は正常に戻る、「过去」は正常でなくなる（気を失う）などを表します。","ex":[["教室里安静下来了。","教室の中が静かになった。"],["天气热起来了。","暑くなってきた。"],["他醒过来了。","彼は意識を取り戻した。"]]},
{"id":"r5-046","text":"（1）动词/形容词+得+动词短语","ja":"「～得＋動詞句」で「～して（その結果）…するほどだ」と、様子や程度を表します。","ex":[["他累得不想说话。","彼は疲れて話す気にもならない。"]]},
{"id":"r5-047","text":"（2）动词/形容词+得+主谓短语","ja":"「～得＋主語＋述語」で、動作や状態の結果、何かがどうなるほどかを表します。","ex":[["他累得腿都疼了。","彼は疲れて足まで痛くなった。"]]},
{"id":"r5-048","text":"（3）动词/形容词+得+固定短语","ja":"「～得＋成語・決まった言い方」で、様子を生き生きと表します。","ex":[["大家高兴得手舞足蹈。","みんなうれしくて小躍りした。"],["他忙得不可开交。","彼は忙しくてどうにもならない。"]]},
{"id":"r5-049","text":"（1）表示存在、具有：主语+有+着+宾语","ja":"「主語＋有着＋目的語」で「～を持っている・～がある」と、抽象的なものの存在を表します（書き言葉的）。","ex":[["中国有着悠久的历史。","中国には長い歴史がある。"]]},
{"id":"r5-050","text":"（2）表示附着：主语+动词+有+宾语","ja":"「動詞＋有」で、何かが表面に付いている・書かれていることを表します（写有＝書いてある）。","ex":[["信封上写有他的名字。","封筒には彼の名前が書いてある。"]]},
{"id":"r5-051","text":"（1）主语+把+宾语+一+动词","ja":"「把＋目的語＋一＋動詞」で「さっと～すると」と、短くすばやい動作を表し、後に続く結果を述べます。","ex":[["他把门一关，就走了。","彼はドアをバタンと閉めて、行ってしまった。"]]},
{"id":"r5-052","text":"（2）主语+把+宾语1+动词+宾语2","ja":"「把＋A＋動詞＋B」で、AをBに～する（AのことをBに話す・AをBとみなす）を表します。","ex":[["我把这件事告诉了妈妈。","私はこのことを母に話した。"],["大家把他当作自己的哥哥。","みんなは彼を自分の兄のように思っている。"]]},
{"id":"r5-053","text":"前后两个动词性词语具有因果、转折、条件关系","ja":"動詞句を二つ続けて、原因と結果、逆接、条件などの関係を表す連動文です。","ex":[["他生病住院了。","彼は病気で入院した。"],["我有事要先走。","用事があるので先に失礼します。"]]},
{"id":"r5-054","text":"A+形容词+B+数量补语","ja":"「A＋形容詞＋B＋数量」で、AとBの差を表します（「A比B＋形容詞＋数量」と同じ意味）。","ex":[["哥哥大我三岁。","兄は私より3歳年上だ。"]]},
{"id":"r5-055","text":"主语+被/叫/让+宾语+给+动词+其他成分","ja":"受け身文で、動詞の前に「给」を加えて、被害の気持ちを強めることがあります（話し言葉）。","ex":[["我的自行车被人给骑走了。","私の自転車は誰かに乗っていかれてしまった。"]]},
{"id":"r5-056","text":"……，便……","ja":"「……，便……」で「～すると、すぐに…」と、続いて起こることを表します（「就」の書き言葉的な形）。","ex":[["他一下课便去了图书馆。","彼は授業が終わるとすぐ図書館へ行った。"]]},
{"id":"r5-057","text":"或是……，或是……","ja":"「或是A，或是B」で「AかBか（どちらか）」を表します（「或者」と同じ）。","ex":[["周末我或是在家休息，或是出去走走。","週末は家で休むか、外を散歩するかです。"]]},
{"id":"r5-058","text":"一旦……，就……","ja":"「一旦A，就B」で「いったんAしたら、B」を表します。","ex":[["一旦决定了，就不要后悔。","いったん決めたら、後悔してはいけない。"]]},
{"id":"r5-059","text":"假如……，（就）……","ja":"「假如A，（就）B」で「もしAなら、B」と仮定を表します（書き言葉的）。","ex":[["假如我是你，我就不去了。","もし私があなたなら、行かないでしょう。"]]},
{"id":"r5-060","text":"万一……，（就）……","ja":"「万一A，（就）B」で「万一Aしたら、B」と、望ましくないことの仮定を表します。","ex":[["万一下雨，我们就改天再去。","万一雨が降ったら、日を改めて行きましょう。"]]},
{"id":"r5-061","text":"……，要不然/不然……","ja":"「A，要不然／不然B」で「Aしなさい。そうでないとB」を表します。","ex":[["快走吧，不然就赶不上车了。","早く行こう、そうしないとバスに間に合わない。"]]},
{"id":"r5-062","text":"……，因而……","ja":"「A，因而B」で「Aなので、したがってB」と結果を表します（書き言葉的）。","ex":[["他学习很努力，因而成绩提高得很快。","彼はよく勉強したので、成績が急速に上がった。"]]},
{"id":"r5-063","text":"……，可见……","ja":"「A，可见B」で「Aである。このことからBがわかる」を表します。","ex":[["这么简单的问题都答错了，可见他没有认真准备。","こんな簡単な問題も間違えたことから、彼がまじめに準備していなかったことがわかる。"]]},
{"id":"r5-064","text":"哪怕……，也……","ja":"「哪怕A，也B」で「たとえAでも B」を表します。","ex":[["哪怕只有一点儿希望，我们也不放弃。","たとえわずかな希望しかなくても、私たちはあきらめない。"]]},
{"id":"r5-065","text":"不但不/不但没有……，反而……","ja":"「不但不／不但没有A，反而B」で「Aしないどころか、かえってB」を表します。","ex":[["他不但没生气，反而笑了。","彼は怒るどころか、かえって笑った。"]]},
{"id":"r5-066","text":"不是……，还/还是……","ja":"「不是A，还（是）B」で「Aであるだけでなく、Bでもある」と、さらに付け加えます。","ex":[["他不是普通的老师，还是有名的作家。","彼はただの先生ではなく、有名な作家でもある。"]]},
{"id":"r5-067","text":"……，为的是……","ja":"「A，为的是B」で「Aするのは、Bのためだ」と目的を表します。","ex":[["我每天早起，为的是锻炼身体。","毎日早起きするのは、体を鍛えるためです。"]]},
{"id":"r5-068","text":"没有……就没有……","ja":"「没有A就没有B」で「AがなければBもない」を表します。","ex":[["没有你的帮助，就没有我的今天。","あなたの助けがなければ、今の私はありません。"]]},
{"id":"r5-069","text":"不……不……","ja":"「不A不B」で「AしなければBしない」を表します（不见不散＝会うまで待つ）。","ex":[["明天八点，不见不散！","明日8時に。会うまで待っていますね。"],["这个问题不讨论不行。","この問題は話し合わないわけにはいかない。"]]},
{"id":"r5-070","text":"再……也……","ja":"「再＋形容詞・動詞……也……」で「どんなに～でも」を表します。","ex":[["工作再忙，也要注意身体。","仕事がどんなに忙しくても、体には気をつけて。"]]},
{"id":"r6-001","text":"超—、多—、反—、无—、亚—、准—","ja":"語の前について新しい語を作る要素です。超＝超～（超大）、多＝多～（多功能＝多機能）、反＝反～（反作用）、无＝無～（无人）、亚＝亜～・二番目（亚军＝準優勝）、准＝準～（准妈妈＝もうすぐ母になる人）。","ex":[["这是一款多功能手机。","これは多機能の携帯電話です。"],["他得了亚军。","彼は準優勝した。"]]},
{"id":"r6-002","text":"—化、—式、—型、—性","ja":"語の後ろについて新しい語を作る要素です。～化（现代化）、～式（中式＝中国式）、～型（大型）、～性（积极性）。","ex":[["这是一家中式饭店。","これは中国式のレストランです。"],["城市越来越现代化了。","都市はますます近代化している。"]]},
{"id":"r6-003","text":"人家","ja":"「人家」は「ほかの人・あの人」を指します。親しい間柄では、話し手自身（わたし）を甘えて指すこともあります。","ex":[["人家都走了，你还不走？","ほかの人はみんな帰ったのに、まだ帰らないの？"]]},
{"id":"r6-004","text":"专用名量词：串、滴、枝、扇、卷¹、卷²","ja":"名詞ごとの量詞です。串＝つながったもの（ぶどう・鍵）、滴＝しずく、枝＝枝・花・ペン、扇＝ドア・窓、卷＝巻いたもの・本の巻を数えます。","ex":[["一串钥匙","鍵ひと束"],["房间里有两扇窗户。","部屋には窓が2つある。"]]},
{"id":"r6-005","text":"番","ja":"「番」は手間や時間のかかる動作を「ひとしきり」と数えます。","ex":[["他认真考虑了一番。","彼はじっくりと考えた。"]]},
{"id":"r6-006","text":"特、异常、较为","ja":"「特」は「特に・非常に」、「异常」は「ことのほか」、「较为」は「比較的」を表します（書き言葉的）。","ex":[["今年夏天异常炎热。","今年の夏はことのほか暑い。"],["这个办法较为合适。","この方法は比較的適切だ。"]]},
{"id":"r6-007","text":"净、一同、大都","ja":"「净」は「～ばかり」、「一同」は「一緒に」、「大都」は「大部分は・ほとんど」を表します。","ex":[["他净说些没用的话。","彼は役に立たないことばかり言う。"],["来参加的人大都是学生。","参加者のほとんどは学生だ。"]]},
{"id":"r6-008","text":"一时、不时、仍旧、依旧、一向","ja":"「一时」は「一時的に・とっさに」、「不时」は「時々」、「仍旧・依旧」は「依然として」、「一向」は「これまでずっと」を表します。","ex":[["我一时想不起他的名字。","とっさに彼の名前が思い出せない。"],["他一向很认真。","彼はこれまでずっとまじめだ。"]]},
{"id":"r6-009","text":"一再、再三","ja":"「一再・再三」は「何度も・再三」を表します。","ex":[["老师一再提醒我们注意安全。","先生は私たちに安全に気をつけるよう何度も注意した。"]]},
{"id":"r6-010","text":"不禁、赶忙、特地、特意、偷偷","ja":"「不禁」は「思わず」、「赶忙」は「急いで」、「特地・特意」は「わざわざ」、「偷偷」は「こっそり」を表します。","ex":[["听到这个消息，她不禁哭了起来。","その知らせを聞いて、彼女は思わず泣き出した。"],["他特意来看我。","彼はわざわざ私に会いに来た。"]]},
{"id":"r6-011","text":"未必","ja":"「未必」は「必ずしも～とは限らない」を表します。","ex":[["他说的未必是真的。","彼の言うことが本当だとは限らない。"]]},
{"id":"r6-012","text":"恰好、倒是、干脆、明明、总算","ja":"「恰好」は「ちょうど」、「倒是」は「意外にも・～ではあるが」、「干脆」は「いっそ」、「明明」は「明らかに」、「总算」は「やっと」を表します。","ex":[["你来得恰好，我正要找你。","ちょうどいいところに来たね、探そうと思っていたんだ。"],["等了很久，车总算来了。","長く待って、やっと車が来た。"]]},
{"id":"r6-013","text":"于","ja":"「于」は「～に・～で・～から」と、時間や場所などを表します（書き言葉）。","ex":[["这所大学建于1950年。","この大学は1950年に創立された。"]]},
{"id":"r6-014","text":"至于","ja":"「至于」は「～については・～に至っては」と、話題を変えるときに使います。","ex":[["我只负责翻译，至于价格的问题，你得问经理。","私は通訳を担当しているだけです。価格については、マネージャーに聞いてください。"]]},
{"id":"r6-015","text":"因","ja":"「因」は「～のために・～によって」と原因を表します（書き言葉）。","ex":[["比赛因雨推迟。","試合は雨のため延期された。"]]},
{"id":"r6-016","text":"除","ja":"「除」は「～を除いて・～のほかに」を表します（「除了」の書き言葉的な形）。","ex":[["除他以外，大家都同意了。","彼以外はみんな賛成した。"]]},
{"id":"r6-017","text":"不料","ja":"「不料」は「意外にも・思いがけず」と、予想外のことが起きたことを表します。","ex":[["我本来想早点儿到，不料路上堵车了。","早めに着くつもりだったのに、思いがけず渋滞した。"]]},
{"id":"r6-018","text":"所","ja":"「（主語＋）所＋動詞＋的＋名詞」の形で名詞を修飾します（書き言葉）。「为……所＋動詞」は受け身を表します。","ex":[["这是我所知道的情况。","これが私の知っている状況です。"],["他的意见为大家所接受。","彼の意見はみんなに受け入れられた。"]]},
{"id":"r6-019","text":"啦、嘛","ja":"「啦」は「了＋啊」が一つになった形で、感嘆や軽い気持ちを表します。「嘛」は「当然でしょう・～じゃない」という気持ちを表します。","ex":[["我们赢啦！","勝ったぞ！"],["有问题就问嘛。","わからないことがあれば聞けばいいじゃない。"]]},
{"id":"r6-020","text":"也好","ja":"「A也好，B也好」で「AにしてもBにしても」、また「～もいいだろう」と、しかたなく認める気持ちを表します。","ex":[["你去也好，不去也好，都得告诉我。","行くにしても行かないにしても、私に知らせてね。"],["这样也好。","それもいいでしょう。"]]},
{"id":"r6-021","text":"A这A那","ja":"「A这A那」は「あれこれ～する」と、いろいろなことをする様子を表します（问这问那＝あれこれ聞く）。","ex":[["妈妈总是问这问那。","母はいつもあれこれ聞いてくる。"]]},
{"id":"r6-022","text":"左A右B","ja":"「左A右B」は同じような動作を何度も繰り返すことを表します（左思右想＝あれこれ考える）。","ex":[["我左思右想，还是决定去。","あれこれ考えて、やはり行くことにした。"]]},
{"id":"r6-023","text":"好（不）容易","ja":"「好容易」「好不容易」はどちらも「やっとのことで・苦労して」を表します（「不」があっても意味は同じ）。","ex":[["我好不容易才找到他家。","私はやっとのことで彼の家を見つけた。"]]},
{"id":"r6-024","text":"那倒（也）是","ja":"「那倒（也）是」は「それは確かにそうだ」と、相手の意見を認めるときに使います。","ex":[["——这儿离车站太远了。——那倒也是。","――ここは駅から遠すぎるよ。――それは確かにそうだね。"]]},
{"id":"r6-025","text":"算了","ja":"「算了」は「もういい・やめておこう」と、あきらめたり話を打ち切ったりするときに使います。","ex":[["算了，我们不去了。","もういいよ、行くのはやめよう。"]]},
{"id":"r6-026","text":"得了","ja":"「得了」は「もういい・やめなさい」、また「それでいい」と同意や決定を表します（話し言葉）。","ex":[["得了，别说了。","もういいから、言わないで。"],["你明天来就得了。","明日来てくれればそれでいい。"]]},
{"id":"r6-027","text":"A一+量词，B一+量词","ja":"「A一＋量詞，B一＋量詞」で「あちらに一つ、こちらに一つ」と、ばらばらに散らばっている様子を表します。","ex":[["书这儿一本，那儿一本，到处都是。","本がこっちに1冊、あっちに1冊と、そこらじゅうにある。"]]},
{"id":"r6-028","text":"东一A，西一A","ja":"「东一A，西一A」で「あちこちに～」と、まとまりなく散らばっている様子を表します。","ex":[["他东一句，西一句，不知道在说什么。","彼はとりとめなく話して、何を言っているのかわからない。"]]},
{"id":"r6-029","text":"到……为止","ja":"「到……为止」で「～までで（終わり）」と、区切りを表します。","ex":[["今天的课就到这儿为止。","今日の授業はここまでです。"]]},
{"id":"r6-030","text":"X到Y头上来了","ja":"「X到Y头上来了」で「（よくないことが）Yにまで及んできた」と、不満や驚きを表します。","ex":[["你怎么管到我头上来了？","どうして私のことにまで口を出すの？"]]},
{"id":"r6-031","text":"不X不……，一X……","ja":"「不X不……，一X……」で「Xしないうちは何ともないが、Xしてみると…」を表します。","ex":[["不看不知道，一看吓一跳。","見るまでは知らなかったが、見てびっくりした。"]]},
{"id":"r6-032","text":"好你个X","ja":"「好你个X」で「この～め」と、相手への不満や驚き（時に親しみ）を表します（話し言葉）。","ex":[["好你个小王，又迟到了！","この王くんめ、また遅刻か！"]]},
{"id":"r6-033","text":"早（也）不X，晚（也）不X","ja":"「早（也）不X，晚（也）不X」で「よりによってこんな時に～する」と、タイミングの悪さへの不満を表します。","ex":[["早不下雨，晚不下雨，偏偏今天下雨。","よりによって今日雨が降るなんて。"]]},
{"id":"r6-034","text":"看/瞧+把+宾语（施事）+X得","ja":"「看／瞧把＋人＋X得」で「見て、～がこんなに…になっている」と、その様子を強調します（話し言葉）。","ex":[["看把你高兴得！","まあ、なんてうれしそうなの！"],["瞧把孩子冻得！","見て、子どもがこんなに冷えちゃって。"]]},
{"id":"r6-035","text":"放着X不Y","ja":"「放着X不Y」で「Xがあるのに（それを）Yしない」と、よい条件を生かさないことへの不満を表します。","ex":[["你放着好好的工作不做，为什么要辞职？","せっかくいい仕事があるのに、どうして辞めるの？"]]},
{"id":"r6-036","text":"X了就X了，（没）有……","ja":"「X了就X了，（没）有……」で「～したならしたでいい、…（たいしたことはない）」と、気にしない気持ちを表します。","ex":[["丢了就丢了，没什么大不了的。","なくしたならなくしたでいい、たいしたことじゃない。"]]},
{"id":"r6-037","text":"这/那也不X，那/这也不Y","ja":"「这也不X，那也不Y」で「これも～しない、あれも…しない」と、何をしても満足しないことへの不満を表します。","ex":[["你这也不吃，那也不吃，到底想吃什么？","これも食べない、あれも食べないって、いったい何が食べたいの？"]]},
{"id":"r6-038","text":"X归X，Y归Y","ja":"「X归X，Y归Y」で「XはX、YはY（別だ）」と、二つを混同しないことを表します。","ex":[["朋友归朋友，钱的事要说清楚。","友達は友達、お金のことははっきりさせよう。"]]},
{"id":"r6-039","text":"看你X的/瞧他X的","ja":"「看你X的」で「あなたったら、なんて～なの」と、相手の様子をからかったり、とがめたりします。","ex":[["看你急的，慢慢说。","そんなに焦って。ゆっくり話して。"]]},
{"id":"r6-040","text":"动词/形容词+透+了","ja":"「～透了」で「すっかり～・徹底的に～」を表します。","ex":[["衣服湿透了。","服がびしょぬれになった。"],["这个西瓜熟透了。","このスイカはすっかり熟している。"]]},
{"id":"r6-041","text":"（1）主语（非生物体）+把+宾语+动词+其他成分","ja":"主語が人以外のもの（出来事・天気など）でも「把」構文を使い、それが何かを引き起こしたことを表せます。","ex":[["这场大雨把路都冲坏了。","この大雨で道がすっかり壊れてしまった。"],["这件事把我急坏了。","この件で私はひどく焦った。"]]},
{"id":"r6-042","text":"（2）主语+把+宾语（施事）+动词+其他成分","ja":"「把」の後ろに、実際にその状態になる人を置く形です。思いがけずそうなってしまったことを表します。","ex":[["这个消息把他高兴得跳了起来。","その知らせで彼は跳び上がるほど喜んだ。"]]},
{"id":"r6-043","text":"一时……一时……","ja":"「一时A一时B」で「Aしたかと思うとB」と、状態がくるくる変わることを表します。","ex":[["他一时说要去，一时又说不去。","彼は行くと言ったかと思うと、また行かないと言う。"]]},
{"id":"r6-044","text":"要么……，要么……","ja":"「要么A，要么B」で「AするかBするか（どちらか）」を表します。","ex":[["要么你来，要么我去，都可以。","あなたが来るか私が行くか、どちらでもいい。"]]},
{"id":"r6-045","text":"虽……，但/可/却/也……","ja":"「虽A，但／可／却／也B」で「Aではあるが、B」と逆接を表します（「虽然……但是」の書き言葉的な形）。","ex":[["他虽年轻，但经验很丰富。","彼は若いけれども、経験は豊富だ。"]]},
{"id":"r6-046","text":"凡是……，都……","ja":"「凡是A，都B」で「AであるものはすべてB」を表します。","ex":[["凡是去过那儿的人，都说那儿很美。","そこに行ったことのある人は皆、きれいなところだと言う。"]]},
{"id":"r6-047","text":"除非……，才……","ja":"「除非A，才B」で「AしないかぎりBしない（Aしてはじめて B）」を表します。","ex":[["除非你亲自去请他，他才会来。","あなたが自分で頼みに行かない限り、彼は来ないだろう。"]]},
{"id":"r6-048","text":"除非……，否则/不然……","ja":"「除非A，否则／不然B」で「Aでない限りB」を表します。","ex":[["除非明天下大雨，否则我们一定去。","明日大雨でない限り、私たちは必ず行きます。"]]},
{"id":"r6-049","text":"就算……，也……","ja":"「就算A，也B」で「たとえAでも B」を表します（話し言葉的）。","ex":[["就算你不说，我也知道。","たとえあなたが言わなくても、私にはわかっている。"]]},
{"id":"r6-050","text":"……，以便……","ja":"「A，以便B」で「Bしやすいように Aする」と目的を表します（書き言葉的）。","ex":[["请留下电话号码，以便我们跟你联系。","こちらから連絡できるように、電話番号を残してください。"]]},
{"id":"r79-001","text":"后—、亲—","ja":"「后～」は「～の後の（ポスト～）」（后疫情时代＝ポストコロナ時代）、「亲～」は「～に親しい・～に近い」（亲民＝庶民的で親しみやすい）を表します。","ex":[["我们已经进入了后疫情时代。","私たちはすでにポストコロナ時代に入った。"],["这位市长很亲民。","この市長はとても庶民的で親しみやすい。"]]},
{"id":"r79-002","text":"—观、—鬼、—界、—然、—坛、—为、—制","ja":"語の後ろについて新しい語を作る要素です。～观（人生观＝人生観）、～鬼（胆小鬼＝臆病者）、～界（教育界）、～然（显然＝明らかだ）、～坛（体坛＝スポーツ界）、～为（视为＝～とみなす）、～制（学分制＝単位制）。","ex":[["每个人的人生观都不一样。","人生観は人それぞれ違う。"],["他是个胆小鬼。","彼は臆病者だ。"]]},
{"id":"r79-003","text":"巴不得、并非、除外、犯不着、犯得着、恨不得、可否、可谓、免不了、所谓、有所、予以","ja":"「巴不得・恨不得」は「～したくてたまらない」、「并非」は「決して～ではない」、「除外」は「除く」、「犯不着」は「～するには及ばない」（「犯得着」は反語で「～する必要があるか」）、「可否」は「～してよいかどうか」、「可谓」は「～と言える」、「免不了」は「避けられない」、「所谓」は「いわゆる」、「有所」は「いくらか～する」、「予以」は「～を与える・～する」（書き言葉）を表します。","ex":[["我恨不得马上飞回家。","今すぐ家に飛んで帰りたくてたまらない。"],["事情并非你想的那样。","事情は決してあなたが思っているようではない。"],["为这点小事生气，犯不着。","こんな小さなことで怒るには及ばない。"]]},
{"id":"r79-004","text":"我","ja":"書き言葉では「我＋名詞」で「わが～・当～」を表します（我国＝わが国、我校＝本校、我方＝当方）。","ex":[["我校共有学生五千人。","本校の学生数は計5000人です。"],["我方同意对方的意见。","当方は先方の意見に同意します。"]]},
{"id":"r79-005","text":"彼、这么着、兹","ja":"「彼」は「あれ・相手」（此起彼伏＝あちこちで次々に起こる）、「这么着」は「こうする・このように」（話し言葉）、「兹」は「ここに・今」（公文書などで）を表します。","ex":[["这么着吧，我们明天再谈。","こうしましょう、明日また話しましょう。"],["兹证明该生在我校学习一年。","ここに、本学生が本校で1年間学んだことを証明する。"]]},
{"id":"r79-006","text":"何、怎么着","ja":"「何」は書き言葉の「なに・どの」（何时＝いつ、为何＝なぜ）、「怎么着」は話し言葉の「どうする・どうした」を表します。","ex":[["你为何不早说？","なぜもっと早く言わなかったのですか。"],["怎么着，你不想去了？","どうしたの、行きたくなくなったの？"]]},
{"id":"r79-007","text":"若干","ja":"「若干」は「いくらか・いくつか」と、はっきりしない数量を表します（書き言葉）。","ex":[["我想提出若干建议。","いくつか提案をしたいと思います。"]]},
{"id":"r79-008","text":"重、截、缕、码、枚、摊、丸、则、幢、宗","ja":"名詞ごとの量詞です（書き言葉的なものが多い）。重＝重なり（两重意思＝二重の意味）、截＝切れ端、缕＝筋（光・煙・髪）、码＝事柄（两码事＝別の話）、枚＝小さく平たいもの（硬貨・メダル）、摊＝広がった液体、丸＝丸薬、则＝記事・広告、幢＝建物、宗＝件（事件・取引）を数えます。","ex":[["他得了一枚金牌。","彼は金メダルを1枚獲得した。"],["这是两码事。","それとこれとは別の話だ。"],["今天报上有一则重要新闻。","今日の新聞に重要なニュースが1つ載っている。"]]},
{"id":"r79-009","text":"通","ja":"「通」は「ひとしきり」と、話す・叱る・電話するなどの動作をひと続きとして数えます。","ex":[["他把我批评了一通。","彼は私をひとしきり批判した。"],["我给他打了一通电话。","私は彼に1本電話をかけた。"]]},
{"id":"r79-010","text":"人次","ja":"「人次」は「延べ人数」を表す複合量詞です（1人が3回来れば3人次）。","ex":[["这个展览共接待观众十万人次。","この展覧会は延べ10万人の観客を迎えた。"]]},
{"id":"r79-011","text":"大为、分外、何等、极度、极力、略、略微、颇、稍稍、万分、微、尤为、愈加、越发","ja":"程度を表す副詞です（書き言葉的なものが多い）。「大为」は「大いに」、「分外」は「ひときわ」、「何等」は「なんと～だろう」、「极度」は「極度に」、「极力」は「懸命に」、「略・略微・稍稍・微」は「少し・わずかに」、「颇」は「すこぶる」、「万分」は「この上なく」、「尤为」は「とりわけ」、「愈加・越发」は「ますます」を表します。","ex":[["听了他的话，我大为感动。","彼の話を聞いて、私は大いに感動した。"],["这个问题颇为复杂。","この問題はすこぶる複雑だ。"],["到了晚上，风越发大了。","夜になって、風はいっそう強くなった。"]]},
{"id":"r79-012","text":"大体、概、皆、尽、均、通通、统统、唯、唯独、唯有、无非、一概","ja":"範囲を表す副詞です。「大体」は「おおむね」、「概・一概」は「一律に」、「皆・均・尽」は「みな・すべて」（書き言葉）、「通通・统统」は「全部」（話し言葉）、「唯・唯独・唯有」は「ただ～だけ」、「无非」は「～にすぎない」を表します。","ex":[["我们的意见大体相同。","私たちの意見はおおむね同じだ。"],["大家都来了，唯独他没来。","みんな来たが、彼だけが来なかった。"],["售出商品，一概不退。","販売した商品は一切返品できません。"]]},
{"id":"r79-013","text":"姑且、即、即时、届时、尽早、就此、历来、尚、随即、向来、一经、暂且、早日","ja":"時間を表す副詞です。「姑且・暂且」は「ひとまず」、「即・随即」は「すぐに」、「即时」は「即時に」、「届时」は「その時になったら」、「尽早」は「できるだけ早く」、「就此」は「ここで（～する）」、「历来・向来」は「これまでずっと」、「尚」は「まだ」、「一经」は「いったん～すると」、「早日」は「一日も早く」を表します。","ex":[["会议九点开始，届时请准时参加。","会議は9時に始まります。その際は時間どおりにご参加ください。"],["祝你早日康复！","一日も早いご回復をお祈りします。"],["这个问题暂且不谈。","この問題はひとまずおいておこう。"]]},
{"id":"r79-014","text":"连连、屡次、屡屡、频、时而、时时、相继、一个劲（儿）、一连、再度","ja":"回数・頻度を表す副詞です。「连连」は「しきりに」、「屡次・屡屡・频」は「たびたび」、「时而」は「時々」、「时时」は「常に」、「相继」は「相次いで」、「一个劲儿」は「ひたすら」、「一连」は「立て続けに」、「再度」は「再び」を表します。","ex":[["他连连点头。","彼はしきりにうなずいた。"],["一连下了三天雨。","3日続けて雨が降った。"],["孩子一个劲儿地哭。","子どもはひたすら泣き続けた。"]]},
{"id":"r79-015","text":"按理、按说、百般、不由得、趁机、趁早、大肆、断然、公然、火速、截然、竭力、尽情、就近、刻意、拼命、强行、任意、日趋、如期、擅自、私自、特此、瞎、一并、一举、一手、毅然、有意、照常、照例、照样、执意、骤然、逐一、专程","ja":"動作のしかたを表す副詞です。例えば「按理・按说」は「本来なら」、「不由得」は「思わず」、「趁机」は「機会に乗じて」、「趁早」は「早いうちに」、「尽情」は「思う存分」、「拼命」は「必死に」、「擅自・私自」は「勝手に・無断で」、「如期・照常」は「予定どおり・いつもどおり」、「一举」は「一挙に」、「专程」は「わざわざ（そのために）」、「瞎」は「でたらめに」を表します。","ex":[["按说他早该到了。","本来なら彼はとっくに着いているはずだ。"],["比赛如期举行。","試合は予定どおり行われた。"],["别瞎说！","でたらめを言うな！"]]},
{"id":"r79-016","text":"不见得、绝不、无从、无须、无可、勿","ja":"否定を表す副詞です。「不见得」は「～とは限らない」、「绝不」は「決して～ない」、「无从」は「～しようがない」、「无须」は「～する必要はない」、「无可」は「～しようがない」（无可奈何＝どうしようもない）、「勿」は「～するな」（掲示など）を表します。","ex":[["贵的东西不见得好。","高いものが良いとは限らない。"],["我绝不放弃。","私は決してあきらめない。"],["请勿吸烟。","喫煙はご遠慮ください。"]]},
{"id":"r79-017","text":"必定、必将、不妨、不免、反倒、非得、分明、怪不得、果真、好在、何必、竟、愣、莫非、难怪、宁可、宁愿、碰巧、偏偏、恰巧、切、情愿、势必、索性、万万、未免、务必、幸好、幸亏、终究、何不、何尝、何苦","ja":"話し手の気持ちを表す副詞です。例えば「不妨」は「～してみてもよい」、「怪不得・难怪」は「道理で」、「何必・何苦」は「～することはない」、「莫非」は「まさか～ではあるまい」、「偏偏」は「よりによって」、「索性」は「いっそ」、「务必」は「必ず」、「幸亏・幸好」は「幸いにも」、「未免」は「どうも～すぎる」、「宁可・宁愿」は「むしろ～したい」を表します。","ex":[["你不妨试试。","試してみてもいいんじゃない。"],["怪不得他没来，原来是病了。","道理で彼が来なかったわけだ、病気だったのか。"],["幸亏你提醒了我。","あなたが注意してくれて助かった。"]]},
{"id":"r79-018","text":"乃","ja":"「乃」は「すなわち～である」と、判断を表します（書き言葉。「是」に近い）。","ex":[["失败乃成功之母。","失敗は成功の母である。"]]},
{"id":"r79-019","text":"打","ja":"「打」は「～から」と、時間や場所の起点を表します（話し言葉。「从」と同じ）。","ex":[["打明天起，我每天跑步。","明日から毎日ジョギングします。"],["你打哪儿来？","どこから来たの？"]]},
{"id":"r79-020","text":"当着、就⁶","ja":"「当着＋人（的面）」は「～の目の前で」、「就＋名詞」は「～について」と、話題や対象を表します。","ex":[["他当着大家的面道了歉。","彼はみんなの前で謝った。"],["我们就这个问题进行了讨论。","私たちはこの問題について話し合った。"]]},
{"id":"r79-021","text":"本着、基于、鉴于¹、经、依","ja":"よりどころを表す介詞です（書き言葉）。「本着」は「（方針・精神）に基づいて」、「基于」は「～に基づいて」、「鉴于」は「～にかんがみて」、「经」は「～を経て」、「依」は「～によって・～に従って」を表します。","ex":[["本着互相学习的精神，我们进行了交流。","互いに学び合う精神に基づいて、私たちは交流を行った。"],["经大家讨论，决定明天出发。","みんなで話し合った結果、明日出発することに決めた。"],["依我看，这个办法不错。","私の見るところ、この方法はなかなかよい。"]]},
{"id":"r79-022","text":"鉴于²、况且、免得、若、倘若、以防","ja":"文をつなぐ接続詞です。「鉴于」は「～であることにかんがみて」、「况且」は「その上・まして」、「免得」は「～しないように」、「若・倘若」は「もし」（書き言葉）、「以防」は「～に備えて」を表します。","ex":[["这件衣服太贵了，况且我也不太喜欢。","この服は高すぎるし、それに私もあまり好きではない。"],["多穿点儿，免得感冒。","風邪をひかないように、たくさん着て。"],["带把伞吧，以防下雨。","雨に備えて傘を持っていきなさい。"]]},
{"id":"r79-023","text":"加之、乃至、且","ja":"「加之」は「その上・加えて」、「乃至」は「さらには・ひいては」、「且」は「かつ・しかも」を表します（書き言葉）。","ex":[["天气很冷，加之下着雨，路上人很少。","とても寒く、その上雨も降っていて、道には人が少ない。"],["这个问题影响到全国乃至全世界。","この問題は全国、ひいては全世界に影響する。"],["这里的房子宽敞且明亮。","ここの部屋は広くて、しかも明るい。"]]},
{"id":"r79-024","text":"罢了、也罢、矣","ja":"「罢了」は「～にすぎない」、「也罢」は「まあいいだろう」（「A也罢，B也罢」で「AにしろBにしろ」）、「矣」は文語で完了や感嘆を表します（「了」に近い）。","ex":[["我只是开个玩笑罢了。","ちょっと冗談を言っただけだよ。"],["不去也罢。","行かないならそれもいいだろう。"],["现在后悔，为时晚矣。","今さら後悔しても、もう遅い。"]]},
{"id":"r79-025","text":"爱A不A","ja":"「爱A不A」は「Aしようとしまいと勝手だ」という突き放した気持ち（爱去不去）や、「爱理不理」（まともに相手にしない）のような冷たい態度を表します。","ex":[["你爱去不去，我不管了。","行くも行かないも勝手にして、私は知らない。"],["他对我爱理不理的。","彼は私をまともに相手にしない。"]]},
{"id":"r79-026","text":"半A半B","ja":"「半A半B」は「半分A、半分B」と、二つの状態が混ざっていることを表します（半信半疑、半真半假＝本当とも嘘ともつかない）。","ex":[["听了他的话，我半信半疑。","彼の話を聞いて、私は半信半疑だった。"]]},
{"id":"r79-027","text":"不A不B","ja":"四字の決まった言い方で、「AでもBでもない（ちょうどよい）」（不冷不热、不大不小）、または「AもBもしない」（不慌不忙＝落ち着いて）ことを表します。","ex":[["这件衣服不大不小，正合适。","この服は大きくも小さくもなく、ちょうどいい。"],["他不慌不忙地回答了问题。","彼は落ち着いて質問に答えた。"]]},
{"id":"r79-028","text":"不A而B","ja":"「不A而B」は「AしないのにBする」を表します（不约而同＝示し合わせたわけでもないのに同じことをする、不劳而获＝働かずに手に入れる）。","ex":[["大家不约而同地笑了。","みんなが期せずして一斉に笑った。"],["这个道理不言而喻。","この道理は言うまでもない。"]]},
{"id":"r79-029","text":"东A西B","ja":"「东A西B」は「あちこちでAしたりBしたり」と、動作があちらこちらに及ぶ様子を表します（东张西望＝きょろきょろ見回す、东奔西走＝あちこち奔走する）。","ex":[["他在门口东张西望。","彼は入口できょろきょろ見回している。"],["为了找工作，他东奔西走。","仕事を探すために、彼はあちこち駆け回った。"]]},
{"id":"r79-030","text":"非A非B","ja":"「非A非B」は「AでもBでもない」を表します（非亲非故＝親戚でも知り合いでもない）。","ex":[["我们非亲非故，他却这么帮我。","私たちは親戚でも知り合いでもないのに、彼はこんなに助けてくれた。"]]},
{"id":"r79-031","text":"忽A忽B","ja":"「忽A忽B」は「急にAになったかと思うと急にBになる」と、状態がくるくる変わることを表します。","ex":[["最近天气忽冷忽热。","最近は急に寒くなったり暑くなったりする。"],["灯光忽明忽暗。","明かりが明るくなったり暗くなったりしている。"]]},
{"id":"r79-032","text":"或A或B","ja":"「或A或B」は「AかBか（いずれにしても）」を表します（或多或少＝多かれ少なかれ）。","ex":[["每个人或多或少都有缺点。","誰でも多かれ少なかれ欠点がある。"]]},
{"id":"r79-033","text":"可A可B","ja":"「可A可B」は「AでもBでもよい」と、どちらでも差し支えないことを表します（可有可无＝あってもなくてもよい）。","ex":[["这个东西可有可无。","これはあってもなくてもいいものだ。"],["这个会可开可不开。","この会議は開いても開かなくてもいい。"]]},
{"id":"r79-034","text":"连A带B","ja":"「连A带B」は「AもBもろとも」（连人带车＝人も車も）、または「AしたりBしたり」と、二つの動作が同時に行われることを表します（连说带笑＝笑いながら話す）。","ex":[["孩子们连说带笑地走进教室。","子どもたちはしゃべったり笑ったりしながら教室に入ってきた。"],["连人带车都掉进了河里。","人も車もろとも川に落ちた。"]]},
{"id":"r79-035","text":"七A八B","ja":"「七A八B」は、数が多くて入り乱れている様子を表します（七嘴八舌＝みんなが口々に言う、七上八下＝不安で心が落ち着かない）。","ex":[["大家七嘴八舌地讨论起来。","みんなが口々に議論し始めた。"],["我心里七上八下的。","私は不安で胸がどきどきしている。"]]},
{"id":"r79-036","text":"时A时B","ja":"「时A时B」は「Aになったり Bになったり」と、状態が交互に変わることを表します（时好时坏＝良くなったり悪くなったり）。","ex":[["他的病时好时坏。","彼の病気は良くなったり悪くなったりしている。"],["雨时断时续地下了一整天。","雨は降ったりやんだりしながら一日中続いた。"]]},
{"id":"r79-037","text":"无A不B","ja":"「无A不B」は「BしないAはない」、つまり「どんなAでもBする」と、例外がないことを表します（无话不谈＝何でも話し合う）。","ex":[["我们俩无话不谈。","私たち二人は何でも話せる仲だ。"],["妈妈对我的照顾无微不至。","母は私の世話を細かいところまで行き届かせてくれる。"]]},
{"id":"r79-038","text":"无A可B","ja":"「无A可B」は「BできるAがない」を表します（无话可说＝言うことがない、无家可归＝帰る家がない）。","ex":[["我已经无话可说了。","私にはもう何も言うことはない。"],["地震后很多人无家可归。","地震の後、多くの人が帰る家を失った。"]]},
{"id":"r79-039","text":"自A自B","ja":"「自A自B」は「自分でAし自分でBする」と、動作が自分自身に向かうことを表します（自言自语＝独り言を言う、自作自受＝自業自得）。","ex":[["他一边走一边自言自语。","彼は歩きながら独り言を言っている。"],["这是你自作自受。","それは自業自得だ。"]]},
{"id":"r79-040","text":"不瞒你说","ja":"「不瞒你说」は「実を言うと・正直に言うと」と、本音を打ち明けるときの前置きです。","ex":[["不瞒你说，我也不太懂。","実を言うと、私もあまりわかっていないんだ。"]]},
{"id":"r79-041","text":"不是","ja":"文頭の「不是」は「いや、そうじゃなくて・ちょっと待って」と、相手の言葉を打ち消したり、自分の考えを切り出したりするときの前置きです（話し言葉）。","ex":[["不是，你听我解释。","いや、ちょっと説明を聞いて。"]]},
{"id":"r79-042","text":"不是我说你","ja":"「不是我说你」は「言わせてもらうけど」と、相手を注意したり批判したりするときの前置きです。","ex":[["不是我说你，你也太粗心了。","言わせてもらうけど、あなたはあまりにも不注意だよ。"]]},
{"id":"r79-043","text":"反过来（说）","ja":"「反过来（说）」は「逆に言えば・反対に」と、逆の面から述べるときの前置きです。","ex":[["压力能让人进步，反过来说，压力太大也会让人生病。","プレッシャーは人を成長させるが、逆に言えば、大きすぎると病気にもなる。"]]},
{"id":"r79-044","text":"概括来说","ja":"「概括来说」は「まとめて言うと」と、要点をまとめるときの前置きです。","ex":[["概括来说，这次活动非常成功。","まとめて言うと、今回のイベントは大成功だった。"]]},
{"id":"r79-045","text":"归根到底","ja":"「归根到底」は「結局のところ・つまるところ」と、根本の原因や結論を述べるときに使います。","ex":[["归根到底，还是方法的问题。","結局のところ、やはりやり方の問題だ。"]]},
{"id":"r79-046","text":"话是这么说","ja":"「话是这么说」は「それはそうだけれど」と、相手の言うことを一応認めつつ、違う考えを述べるときの前置きです。","ex":[["话是这么说，可真做起来并不容易。","それはそうだけど、実際にやってみると簡単じゃない。"]]},
{"id":"r79-047","text":"话（又）说回来","ja":"「话（又）说回来」は「とはいえ・そうは言っても」と、それまでとは別の面から述べるときの前置きです。","ex":[["这家店贵是贵，不过话说回来，东西确实好。","この店は高いことは高いが、とはいえ品物は確かに良い。"]]},
{"id":"r79-048","text":"换句话说","ja":"「换句话说」は「言い換えれば」を表します。","ex":[["他没有回答，换句话说，他不同意。","彼は答えなかった。言い換えれば、賛成していないということだ。"]]},
{"id":"r79-049","text":"简（而）言之","ja":"「简（而）言之」は「簡単に言えば・要するに」を表します（書き言葉的）。","ex":[["简而言之，我们需要更多的时间。","要するに、私たちにはもっと時間が必要だ。"]]},
{"id":"r79-050","text":"可不（是嘛）","ja":"「可不（是嘛）」は「そうだよね・まったくだ」と、相手の言葉に強く同意するときに使います（話し言葉）。","ex":[["——今天真冷啊！——可不是嘛！","――今日は本当に寒いね！――まったくだよ！"]]},
{"id":"r79-051","text":"老实说","ja":"「老实说」は「正直に言うと」と、本当の気持ちを述べるときの前置きです。","ex":[["老实说，我不太喜欢这个电影。","正直に言うと、この映画はあまり好きではない。"]]},
{"id":"r79-052","text":"（你）还别说","ja":"「（你）还别说」は「意外なことに・実際のところ」と、予想に反して認めざるを得ないことを述べるときに使います（話し言葉）。","ex":[["你还别说，这个办法真管用。","意外なことに、この方法は本当に効き目がある。"]]},
{"id":"r79-053","text":"你看你","ja":"「你看你」は「ほら、あなたったら」と、相手の失敗や様子をとがめたり、からかったりするときに使います。","ex":[["你看你，又把衣服弄脏了。","ほら、また服を汚して。"]]},
{"id":"r79-054","text":"说到哪儿去了","ja":"「（你）说到哪儿去了」は「何をおっしゃいますか・とんでもない」と、相手の謝罪やお礼、誤解を打ち消すときに使います。","ex":[["——给你添麻烦了。——你说到哪儿去了！","――ご迷惑をおかけしました。――何をおっしゃいますか！"]]},
{"id":"r79-055","text":"说真的","ja":"「说真的」は「本当のところ・まじめな話」と、本気の話を切り出すときの前置きです。","ex":[["说真的，我很佩服你。","まじめな話、あなたには本当に感心している。"]]},
{"id":"r79-056","text":"退一步说","ja":"「退一步说」は「一歩譲って言えば・仮にそうだとしても」と、譲歩して述べるときの前置きです。","ex":[["退一步说，就算他错了，你也不应该骂他。","一歩譲って、たとえ彼が間違っていたとしても、ののしるべきではない。"]]},
{"id":"r79-057","text":"无论如何","ja":"「无论如何」は「どうしても・いずれにせよ」を表します。","ex":[["无论如何，你明天一定要来。","何があっても、明日は必ず来てね。"]]},
{"id":"r79-058","text":"要（让）我说","ja":"「要（让）我说」は「私に言わせれば」と、自分の意見を述べるときの前置きです。","ex":[["要我说，你还是先休息几天吧。","私に言わせれば、まずは何日か休んだほうがいいよ。"]]},
{"id":"r79-059","text":"这不","ja":"「这不」は「ほら（このとおり）」と、今述べたことの具体例や証拠をすぐ後に示すときに使います（話し言葉）。","ex":[["他说今天会来，这不，人已经到了。","彼は今日来ると言っていたが、ほら、もう来ている。"]]},
{"id":"r79-060","text":"这样一来","ja":"「这样一来」は「こうなると・そうすると」と、前のことから生じる結果を述べるときに使います。","ex":[["地铁通了，这样一来，上班方便多了。","地下鉄が開通した。これで通勤がずっと便利になった。"]]},
{"id":"r79-061","text":"真是的","ja":"「真是的」は「まったくもう」と、不満やいらだちを表します（話し言葉）。","ex":[["真是的，怎么又下雨了！","まったくもう、また雨か！"]]},
{"id":"r79-062","text":"综上所述","ja":"「综上所述」は「以上をまとめると」と、文章や発表の結論を述べるときに使います（書き言葉）。","ex":[["综上所述，这个计划是可行的。","以上をまとめると、この計画は実行可能である。"]]},
{"id":"r79-063","text":"总的来说","ja":"「总的来说」は「全体的に言うと・総じて」を表します。","ex":[["总的来说，这次考试大家考得不错。","総じて、今回の試験はみんなよくできた。"]]},
{"id":"r79-064","text":"总而言之","ja":"「总而言之」は「要するに・つまり」と、まとめを述べるときに使います。","ex":[["总而言之，健康最重要。","要するに、健康が一番大切だ。"]]},
{"id":"r79-065","text":"X到这个地步/份上","ja":"「X到这个地步／份上」は「～がこんなところにまでなる」と、事態がひどいところまで来たことを表します。","ex":[["事情已经发展到这个地步了，后悔也没用。","事態はもうここまで来てしまった。後悔しても無駄だ。"],["话都说到这个份上了，你还不明白吗？","ここまで言っても、まだわからないの？"]]},
{"id":"r79-066","text":"X得要命/要死","ja":"「X得要命／要死」は「死ぬほど～・ものすごく～」と、程度がきわめて高いことを表します（話し言葉）。","ex":[["今天热得要命。","今日は死ぬほど暑い。"],["我累得要死。","疲れて死にそうだ。"]]},
{"id":"r79-067","text":"X都不/没X","ja":"「X都不／没X」は「～さえしない・～すらしなかった」と、まったくしないことを強調します。","ex":[["他看都没看就签了字。","彼は見もしないでサインした。"],["这种菜我尝都不想尝。","こんな料理は味見すらしたくない。"]]},
{"id":"r79-068","text":"X就X个Y","ja":"「X就X个Y」は「～するなら思い切りYになるまで～する」と、とことんやる気持ちを表します。","ex":[["要玩就玩个痛快！","遊ぶなら思い切り遊ぼう！"]]},
{"id":"r79-069","text":"X了Y，Y了X","ja":"「X了Y，Y了X」は「XしてはYし、YしてはXする」と、二つの動作を繰り返すことを表します（吃了睡，睡了吃＝食べては寝、寝ては食べる）。","ex":[["放假以后，他每天吃了睡，睡了吃。","休みに入ってから、彼は毎日食べては寝、寝ては食べている。"]]},
{"id":"r79-070","text":"X也好，Y也罢","ja":"「X也好，Y也罢」は「XにしてもYにしても（どちらでも）」を表します。","ex":[["你同意也好，不同意也罢，我都要去。","あなたが賛成しようとしまいと、私は行く。"]]},
{"id":"r79-071","text":"别提（有）多+形容词+了","ja":"「别提（有）多＋形容詞＋了」は「言うまでもないほど～だ・それはもう～だ」と、程度の高さを強調します（話し言葉）。","ex":[["听到这个消息，他别提多高兴了。","その知らせを聞いて、彼はそれはもう大喜びだった。"]]},
{"id":"r79-072","text":"不亚于……","ja":"「不亚于……」は「～に劣らない」を表します。","ex":[["他的汉语水平不亚于中国人。","彼の中国語のレベルは中国人に劣らない。"]]},
{"id":"r79-073","text":"不知X是/才好","ja":"「不知（道）＋疑問詞…（是／才）好」は「どう～したらよいかわからない」と、困っている気持ちを表します。","ex":[["我不知道说什么才好。","何と言ったらよいかわからない。"],["他急得不知怎么办才好。","彼は焦って、どうしたらいいかわからなかった。"]]},
{"id":"r79-074","text":"动不动就……","ja":"「动不动就……」は「何かというとすぐ～する」と、よくないことがすぐ起こることを表します。","ex":[["这孩子动不动就哭。","この子は何かというとすぐ泣く。"]]},
{"id":"r79-075","text":"动词+得个……","ja":"「動詞＋得个……」は「～して…という結果になる」と、動作の結果を表します。「落得个」（～という羽目になる）のように、よくない結果によく使います。","ex":[["他不听别人的意见，结果落得个失败的下场。","彼は人の意見を聞かず、結局失敗という結末になった。"]]},
{"id":"r79-076","text":"动词+个X","ja":"「動詞＋个＋X」は、動作を気軽に、または徹底的に行うことを表します（问个明白＝はっきりするまで聞く、说个不停＝しゃべり続ける）。","ex":[["这件事我一定要问个明白。","この件は必ずはっきりするまで聞く。"],["孩子们说个不停。","子どもたちはずっとしゃべり続けている。"]]},
{"id":"r79-077","text":"该X（就）X，该Y（就）Y","ja":"「该X（就）X，该Y（就）Y」は「Xすべき時はXし、Yすべき時はYする」と、場面に応じてけじめをつけることを表します。","ex":[["该学习就学习，该玩就玩。","勉強すべき時は勉強し、遊ぶべき時は遊ぶ。"]]},
{"id":"r79-078","text":"何至于……","ja":"「何至于……」は「どうして～するほどのことがあろうか」と、そこまでにはならないはずだという気持ちを表します（反語）。","ex":[["要是早点儿去医院，何至于病得这么重？","もっと早く病院に行っていれば、こんなに重くなることはなかっただろうに。"]]},
{"id":"r79-079","text":"仅次于X","ja":"「仅次于X」は「Xに次ぐ（Xの次に位置する）」を表します。","ex":[["他的成绩在班里仅次于小王。","彼の成績はクラスで王さんに次いで2番目だ。"]]},
{"id":"r79-080","text":"看在X的面子上","ja":"「看在X的面子上」は「Xの顔を立てて・Xに免じて」を表します。","ex":[["看在你的面子上，这次就原谅他吧。","あなたの顔を立てて、今回は彼を許そう。"]]},
{"id":"r79-081","text":"没什么+动词+头儿","ja":"「没什么＋動詞＋头儿」は「～する値打ちがあまりない」を表します（没什么看头儿＝見るほどのものはない）。","ex":[["这个地方没什么玩头儿。","ここは遊ぶ値打ちがあまりない。"]]},
{"id":"r79-082","text":"没什么好+动词+的","ja":"「没什么好＋動詞＋的」は「～するほどのことは何もない」を表します。","ex":[["这件事没什么好担心的。","このことは何も心配することはない。"]]},
{"id":"r79-083","text":"莫过于……","ja":"「莫过于……」は「～に勝るものはない・～が一番だ」を表します（書き言葉）。","ex":[["人生最大的快乐莫过于帮助别人。","人生最大の喜びは、人を助けることに勝るものはない。"]]},
{"id":"r79-084","text":"你说你一个X，……","ja":"「你说你一个X，……」は「あなたはXなのに、（どうして）…」と、相手の立場にふさわしくない行動を責めたり、あきれたりするときに使います。","ex":[["你说你一个大学生，怎么连这个字都不认识？","大学生ともあろう人が、どうしてこの字も読めないの？"]]},
{"id":"r79-085","text":"什么A的B的","ja":"「什么A的B的」は「Aだの Bだの」と、いろいろなものを並べて挙げるときに使います。","ex":[["什么吃的穿的，都给他准备好了。","食べ物だの着る物だの、すべて彼のために用意した。"]]},
{"id":"r79-086","text":"视……而定","ja":"「视……而定」は「～によって決める・～次第である」を表します（書き言葉）。","ex":[["去不去，视天气情况而定。","行くかどうかは天気次第で決める。"]]},
{"id":"r79-087","text":"谈何……","ja":"「谈何……」は「どうして～などと言えようか」と、反語で非常に難しいことを表します（谈何容易＝言うほどたやすくない）。","ex":[["一年学好汉语，谈何容易！","1年で中国語をマスターするなんて、言うほど簡単ではない！"]]},
{"id":"r79-088","text":"无非/不过/只是……罢了/而已","ja":"「无非／不过／只是……罢了／而已」は「ただ～にすぎない」と、たいしたことではないことを表します。","ex":[["我不过随便问问而已。","ちょっと聞いてみただけです。"],["他无非是想让你高兴罢了。","彼はただあなたを喜ばせたいだけだ。"]]},
{"id":"r79-089","text":"想X之所想，急X之所急","ja":"「想X之所想，急X之所急」は「Xの考えることを考え、Xの急ぐことを急ぐ」と、相手の立場に立って親身に対応することを表します（書き言葉）。","ex":[["我们要想顾客之所想，急顾客之所急。","私たちはお客様の身になって考え、お客様の急ぎに応えなければならない。"]]},
{"id":"r79-090","text":"向……致以……","ja":"「向……致以……」は「～に…を申し上げる」と、あいさつや感謝などを丁寧に述べる書き言葉の形です。","ex":[["向大家致以节日的问候！","皆さんに祝日のごあいさつを申し上げます。"]]},
{"id":"r79-091","text":"要X有/没X，要Y有/没Y","ja":"「要X有X，要Y有Y」は「XもYも備わっている」、「要X没X，要Y没Y」は「XもYも何もない」を表します。","ex":[["他要钱没钱，要房没房。","彼はお金もなければ家もない。"],["这个公司要人有人，要技术有技术。","この会社は人材もいれば技術もある。"]]},
{"id":"r79-092","text":"因……而……","ja":"「因……而……」は「～によって…する・～のために…」と、原因と結果を表します（書き言葉）。","ex":[["他因生病而没参加考试。","彼は病気のため試験を受けなかった。"],["这里因风景美而出名。","ここは景色が美しいことで有名だ。"]]},
{"id":"r79-093","text":"有何X","ja":"「有何X」は書き言葉で「何のXがあるか」を表し、反語で「何のXもない」の意味でもよく使います（有何不可＝かまわないではないか）。","ex":[["这样做有何不可？","こうして何がいけないのか。"]]},
{"id":"r79-094","text":"有什么+动词+头儿","ja":"「有什么＋動詞＋头儿」は「～する値打ちなどあるものか」と、反語で値打ちがないことを表します。","ex":[["这种电影有什么看头儿？","こんな映画のどこに見る値打ちがあるの？"]]},
{"id":"r79-095","text":"（在）……之余","ja":"「（在）……之余」は「～の合間に・～のほかに」を表します（書き言葉）。","ex":[["工作之余，他喜欢画画儿。","仕事の合間に、彼は絵を描くのが好きだ。"]]},
{"id":"r79-096","text":"值此……之际，……","ja":"「值此……之际，……」は「～にあたり・～に際して」と、あいさつや式辞で使う書き言葉の形です。","ex":[["值此新年之际，祝大家身体健康！","新年にあたり、皆さんのご健康をお祈りします。"]]},
{"id":"r79-097","text":"A+形容词+于/过+B","ja":"「A＋形容詞＋于／过＋B」は「AはBより～だ」と、比較を表す書き言葉的な形です。","ex":[["今年的收入高于去年。","今年の収入は去年より多い。"],["事实胜于雄辩。","事実は雄弁に勝る。"]]},
{"id":"r79-098","text":"一来……，二来……，三来……","ja":"「一来……，二来……（，三来……）」は「一つには～、二つには…」と、理由などを並べて述べます。","ex":[["我来中国，一来是为了学汉语，二来是想了解中国文化。","私が中国に来たのは、一つには中国語を学ぶため、もう一つには中国文化を知りたいからです。"]]},
{"id":"r79-099","text":"一则……，二则……，三则……","ja":"「一则……，二则……（，三则……）」は「一つには～、二つには…」と、理由などを並べて述べる書き言葉的な形です。","ex":[["这次没去，一则太忙，二则身体不太好。","今回行かなかったのは、一つには忙しすぎたから、二つには体調があまり良くなかったからだ。"]]},
{"id":"r79-100","text":"所谓……，就是……","ja":"「所谓……，就是……」は「いわゆる～とは、…のことだ」と、言葉の意味を説明します。","ex":[["所谓“知己”，就是最了解你的朋友。","いわゆる「知己」とは、あなたを最もよく理解している友人のことだ。"]]},
{"id":"r79-101","text":"或……，或……","ja":"「或……，或……」は「～したり、…したり」「～か…か」と、いくつかの場合を並べます（書き言葉）。","ex":[["周末大家或看书，或运动，过得很充实。","週末にみんなは本を読んだり運動したりして、充実した時間を過ごす。"]]},
{"id":"r79-102","text":"宁可/宁愿……，也不……","ja":"「宁可／宁愿……，也不……」は「たとえ～しても…はしない」と、二つを比べて一方を選ぶ強い気持ちを表します。","ex":[["我宁可走路，也不坐他的车。","歩いたほうがまだましで、彼の車には乗らない。"]]},
{"id":"r79-103","text":"与其……，宁愿/宁可……","ja":"「与其……，宁愿／宁可……」は「～するより、むしろ…したい」を表します。","ex":[["与其在家闲着，我宁愿出去工作。","家でぶらぶらしているより、むしろ働きに出たい。"]]},
{"id":"r79-104","text":"X（倒）是X（了），……","ja":"「X（倒）是X（了），……」は「Xであることはそうだが、…」と、いったん認めてから反対のことを述べます。","ex":[["这件衣服好看倒是好看，就是太贵了。","この服はきれいなことはきれいだが、高すぎる。"]]},
{"id":"r79-105","text":"别看……，……","ja":"「别看……，……」は「～だからといって（見かけで判断してはいけない）…」と、予想に反することを述べます。","ex":[["别看他年纪小，懂的东西可多了。","彼は年は若いけれど、知っていることはとても多い。"]]},
{"id":"r79-106","text":"虽说……，但/可……","ja":"「虽说……，但／可……」は「～とはいうものの、…」と逆接を表します（話し言葉的）。","ex":[["虽说已经是春天了，可天气还很冷。","もう春とはいうものの、まだとても寒い。"]]},
{"id":"r79-107","text":"无论……与否，都……","ja":"「无论……与否，都……」は「～かどうかにかかわらず、…」を表します（書き言葉）。","ex":[["无论成功与否，我们都要努力。","成功するかどうかにかかわらず、私たちは努力しなければならない。"]]},
{"id":"r79-108","text":"凡……（者），均（可）……","ja":"「凡……（者），均（可）……」は「～である者はすべて…（できる）」と、規則や告知などで使う書き言葉の形です。","ex":[["凡本校学生，均可免费参加。","本校の学生は誰でも無料で参加できます。"]]},
{"id":"r79-109","text":"假若/假使……，……","ja":"「假若／假使……，……」は「もし～ならば、…」と仮定を表します（書き言葉）。","ex":[["假若明天下雨，比赛就改期。","もし明日雨なら、試合は延期する。"]]},
{"id":"r79-110","text":"幸亏/幸好……，不然/否则……","ja":"「幸亏／幸好……，不然／否则……」は「幸い～だったからよかったものの、そうでなければ…」を表します。","ex":[["幸亏你提醒了我，不然我就忘了。","あなたが注意してくれてよかった。そうでなければ忘れていた。"]]},
{"id":"r79-111","text":"纵然/纵使……，也……","ja":"「纵然／纵使……，也……」は「たとえ～でも、…」を表します（書き言葉）。","ex":[["纵然困难再大，我们也不会放弃。","たとえ困難がどんなに大きくても、私たちはあきらめない。"]]},
{"id":"r79-112","text":"（因）……，故……","ja":"「（因）……，故……」は「～なので、それゆえ…」と、原因と結果を表します（書き言葉）。","ex":[["因天气原因，故航班推迟起飞。","天候のため、便の出発が遅れます。"]]},
{"id":"r79-113","text":"……，以至（于）……","ja":"「……，以至（于）……」は「～で、その結果…するほどだ」と、程度がはなはだしく、ある結果に至ることを表します。","ex":[["他工作太忙，以至于忘了吃饭。","彼は仕事が忙しすぎて、食事を忘れるほどだった。"]]},
{"id":"r79-114","text":"别说……，都/也……","ja":"「别说……，都／也……」は「～はもちろん、…さえも」と、二つを比べて強調します。","ex":[["别说一个星期，一天我也等不了。","1週間どころか、1日だって待てない。"]]},
{"id":"r79-115","text":"……不说，还……","ja":"「……不说，还……」は「～だけでなく、その上…」と、さらに付け加えます。","ex":[["这家饭店菜贵不说，味道还不好。","このレストランは料理が高いうえに、味も良くない。"]]},
{"id":"r79-116","text":"连……都……，更不用说……了","ja":"「连……都……，更不用说……了」は「～さえ…なのだから、…は言うまでもない」を表します。","ex":[["这个字连老师都不认识，更不用说学生了。","この字は先生さえ知らないのだから、学生は言うまでもない。"]]},
{"id":"r79-117","text":"……尚且……，（更）何况……","ja":"「……尚且……，（更）何况……」は「～でさえ…なのに、まして…はなおさらだ」を表します（書き言葉的）。","ex":[["大人尚且搬不动，何况孩子呢？","大人でさえ運べないのに、まして子どもならなおさらだ。"]]},
{"id":"r79-118","text":"……，更不用说……了","ja":"「……，更不用说……了」は「～だ。…は言うまでもない」と、さらに程度の高いことを付け加えます。","ex":[["他英语说得很好，更不用说汉语了。","彼は英語が上手で、中国語は言うまでもない。"]]},
{"id":"r79-119","text":"为（了）……起见，……","ja":"「为（了）……起见，……」は「～のために（念のため）…」と、目的を表します（書き言葉）。","ex":[["为安全起见，请系好安全带。","安全のため、シートベルトをお締めください。"]]},
{"id":"r79-120","text":"……，以……","ja":"「……，以……」は「～して、それによって…する」と、目的を表します（書き言葉）。","ex":[["我们要努力学习，以提高自己的能力。","自分の能力を高めるために、私たちは努力して学ばなければならない。"]]},
{"id":"r79-121","text":"非得……才……","ja":"「非得……才……」は「どうしても～しなければ…しない」と、必要な条件を強く表します。","ex":[["这件事非得你亲自去才行。","この件はどうしてもあなたが自分で行かないとだめだ。"]]},
{"id":"r79-122","text":"任……也……","ja":"「任……也……」は「どんなに～しても…」と、条件にかかわらず結果が変わらないことを表します。","ex":[["任你怎么说，他也不听。","あなたがどんなに言っても、彼は聞かない。"]]},
{"id":"r79-123","text":"多重并列复句","ja":"多重複文は、複文の中にさらに複文が入った、二層以上の文です。並列の多重複文では、並べた各部分の中にさらに別の関係（因果など）が含まれます。","ex":[["哥哥喜欢运动，因为运动让他快乐；妹妹喜欢读书，因为书让她了解世界。","兄はスポーツが好きだ。スポーツをすると楽しいからだ。妹は読書が好きだ。本で世界を知ることができるからだ。"]]},
{"id":"r79-124","text":"多重转折复句","ja":"いちばん大きな区切りが逆接（～だが…）で、その中にさらに別の関係が含まれる多重複文です。","ex":[["虽然这个工作又累又忙，但是因为能学到很多东西，所以我很喜欢。","この仕事は疲れるし忙しいが、多くのことを学べるので、とても気に入っている。"]]},
{"id":"r79-125","text":"多重假设复句","ja":"いちばん大きな区切りが仮定（もし～なら…）で、その中にさらに別の関係が含まれる多重複文です。","ex":[["如果明天不下雨，而且大家都有时间，我们就去爬山。","もし明日雨が降らず、しかもみんな時間があれば、山登りに行こう。"]]},
{"id":"r79-126","text":"多重因果复句","ja":"いちばん大きな区切りが因果（～なので…）で、その中にさらに別の関係が含まれる多重複文です。","ex":[["因为他不但聪明，而且很努力，所以成绩一直很好。","彼は頭がいいだけでなく努力もしているので、成績はずっと良い。"]]},
{"id":"r79-127","text":"多重递进复句","ja":"いちばん大きな区切りが累加（～だけでなく…も）で、その中にさらに別の関係が含まれる多重複文です。","ex":[["这本书不但内容丰富，而且因为语言简单，连初学者也能看懂。","この本は内容が豊富なだけでなく、言葉がやさしいので、初心者でも読める。"]]},
{"id":"r79-128","text":"时间顺序","ja":"文のまとまり（段落）を、出来事が起きた時間の順に並べて書く方法です。「先……，然后……，最后……」などの言葉がよく使われます。","ex":[["早上我先去了银行，然后去超市买了东西，最后回家做饭。","朝、まず銀行に行き、それからスーパーで買い物をして、最後に家に帰って料理をした。"]]},
{"id":"r79-129","text":"空间顺序","ja":"文のまとまりを、場所の位置関係の順（外から内へ、左から右へなど）に並べて書く方法です。","ex":[["走进大门，左边是图书馆，右边是教学楼，正前方是一个大操场。","正門を入ると、左側に図書館、右側に教室棟、正面には大きなグラウンドがある。"]]},
{"id":"r79-130","text":"逻辑顺序","ja":"文のまとまりを、原因から結果へ、一般から具体へなど、論理の順に並べて書く方法です。「首先……，其次……，因此……」などの言葉がよく使われます。","ex":[["首先，运动能让身体更健康；其次，运动能减轻压力。因此，我们应该每天运动。","まず、運動は体をより健康にする。次に、運動はストレスを減らす。したがって、私たちは毎日運動すべきだ。"]]},
{"id":"r79-131","text":"话题延伸","ja":"前の文の話題を受けて、それに関連する内容へと話を広げていく文のつなぎ方です。「说到……」などがよく使われます。","ex":[["我很喜欢喝茶。说到茶，中国的茶文化有几千年的历史。","私はお茶が大好きだ。お茶と言えば、中国の茶文化には数千年の歴史がある。"]]},
{"id":"r79-132","text":"话题转换","ja":"「另外」「对了」「至于」などを使って、それまでの話題から別の話題に切り替える文のつなぎ方です。","ex":[["工作的事就这么定了。对了，你周末有空吗？","仕事の件はこれで決まりだね。ところで、週末は空いてる？"]]},
{"id":"r79-133","text":"承前省略","ja":"前の文にすでに出てきた主語などを、後の文で省略する方法です。下の例では、後半の主語「小王」が省略されています。","ex":[["小王来到北京以后，找到了工作，还交了很多朋友。","王さんは北京に来てから、仕事を見つけ、友達もたくさんできた。"]]},
{"id":"r79-134","text":"蒙后省略","ja":"後の文に出てくる主語などを、前の文で先に省略する方法です。下の例では、前半の主語「他」が後半に出てくるので省略されています。","ex":[["听到这个消息，他高兴得跳了起来。","その知らせを聞いて、彼は跳び上がって喜んだ。"]]}
];
